 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CTPN_TongVaNguon ON dbo.CHI_TIET_PHIEU_NHAP'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.PHIEU_NHAP p WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaPN FROM inserted UNION SELECT MaPN FROM deleted) z ON z.MaPN=p.MaPN WHERE p.TrangThai<>N''Nháp'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51018,N''Chỉ thay đổi chi tiết phiếu nhập nháp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.PHIEU_NHAP p ON p.MaPN=i.MaPN JOIN dbo.HOA_DON_NHAP h ON h.MaHDN=p.MaHDN JOIN dbo.LO_HANG_HOA l ON l.MaLo=i.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE l.MaHH<>i.MaHH OR l.MaKho<>p.MaKho OR l.MaNCC<>h.MaNCC)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51019,N''Lô nhập phải khớp hàng hóa, kho và nhà cung cấp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' UPDATE p SET TongTien=COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaPN=p.MaPN),0)'+NCHAR(13)+N''+NCHAR(10)+N' FROM dbo.PHIEU_NHAP p WHERE p.MaPN IN(SELECT MaPN FROM inserted UNION SELECT MaPN FROM deleted);'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_CTPX_Nguon ON dbo.CHI_TIET_PHIEU_XUAT'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.PHIEU_XUAT p WITH(UPDLOCK,HOLDLOCK) JOIN(SELECT MaPX FROM inserted UNION SELECT MaPX FROM deleted) z ON z.MaPX=p.MaPX WHERE p.TrangThai<>N''Nháp'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51023,N''Chỉ thay đổi chi tiết phiếu xuất nháp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.PHIEU_XUAT p ON p.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=i.MaCTDT LEFT JOIN dbo.DON_THUOC d ON d.MaDT=c.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.THUOC t ON t.MaThuoc=c.MaThuoc LEFT JOIN dbo.LO_HANG_HOA l ON l.MaLo=i.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE (p.MaLS IS NOT NULL AND(i.MaCTDT IS NULL OR p.MaLS<>d.MaLS OR i.MaHH<>t.MaHH OR i.MaLo IS NULL))'+NCHAR(13)+N''+NCHAR(10)+N' OR (p.MaLS IS NULL AND i.MaCTDT IS NOT NULL) OR(i.MaLo IS NOT NULL AND(l.MaHH<>i.MaHH OR l.MaKho<>p.MaKho)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51024,N''Dòng xuất phải đúng thuốc của đơn/lần khám và đúng lô, kho; xuất nội bộ không dùng MaCTDT.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.[TR_CW_Audit_CAU_HINH_THUOC_KE_DON] ON dbo.[CAU_HINH_THUOC_KE_DON] AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'DECLARE @actor nvarchar(50)=TRY_CONVERT(nvarchar(50),SESSION_CONTEXT(N''RHM.MaTK''));'+NCHAR(13)+N''+NCHAR(10)+N'IF NOT EXISTS(SELECT 1 FROM dbo.TAI_KHOAN t JOIN dbo.NHAN_VIEN n ON n.MaNV=t.MaNV WHERE t.MaTK=@actor AND t.TrangThai=N''Đang hoạt động'' AND n.TrangThai=N''Đang làm việc'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 52120,N''Cấu hình chuyên môn cần người sửa đã xác thực để lưu nhật ký.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'INSERT dbo.NHAT_KY_THAO_TAC(MaNK,MaTK,ThoiGian,HanhDong,LoaiDoiTuong,MaDoiTuong,KetQua,DuLieuTruoc,DuLieuSau)'+NCHAR(13)+N''+NCHAR(10)+N'SELECT N''NK''+CONVERT(nvarchar(36),NEWID()),@actor,SYSDATETIME(),N''Cập nhật cấu hình hỗ trợ'',N''CAU_HINH_THUOC_KE_DON'',COALESCE(i.[MaThuoc],d.[MaThuoc]),N''Thành công'','+NCHAR(13)+N''+NCHAR(10)+N'  CASE WHEN d.[MaThuoc] IS NOT NULL THEN (SELECT d.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) END,'+NCHAR(13)+N''+NCHAR(10)+N'  CASE WHEN i.[MaThuoc] IS NOT NULL THEN (SELECT i.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) END'+NCHAR(13)+N''+NCHAR(10)+N'FROM inserted i FULL JOIN deleted d ON d.[MaThuoc]=i.[MaThuoc];'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
