 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PCAXQ_BaoVe ON dbo.PHAN_CONG_ANH_XQUANG AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N' BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'  SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaPC=d.MaPC WHERE i.MaPC IS NULL)'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 53411,N''Không xóa lịch sử phân công ảnh.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPC=i.MaPC WHERE d.TrangThai=N''Đã hủy'''+NCHAR(13)+N''+NCHAR(10)+N'   OR EXISTS(SELECT i.MaDVThucHien,i.MaNVKyThuat,i.MaNVPhanCong,i.NgayPhanCong EXCEPT SELECT d.MaDVThucHien,d.MaNVKyThuat,d.MaNVPhanCong,d.NgayPhanCong))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 53412,N''Phân công ảnh đã lưu được giữ nguyên; hủy và lập phân công mới.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=i.MaDVThucHien'+NCHAR(13)+N''+NCHAR(10)+N'   JOIN dbo.DICH_VU d ON d.MaDV=s.MaDV JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=s.MaLS'+NCHAR(13)+N''+NCHAR(10)+N'   JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=l.MaPhieu JOIN dbo.NHAN_VIEN n ON n.MaNV=i.MaNVKyThuat'+NCHAR(13)+N''+NCHAR(10)+N'   WHERE d.MaCK<>N''CK004'' OR l.TrangThai<>N''Nháp'' OR p.TrangThai NOT IN(N''Chờ khám'',N''Đang khám'')'+NCHAR(13)+N''+NCHAR(10)+N'    OR(i.TrangThai=N''Đang áp dụng'' AND(n.MaChucVu<>N''CV003'' OR n.TrangThai<>N''Đang làm việc'' OR NOT EXISTS(SELECT 1 FROM dbo.TAI_KHOAN t WHERE t.MaNV=n.MaNV AND t.TrangThai=N''Đang hoạt động''))))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 53413,N''Phân công cần dịch vụ chụp, lượt còn mở và nhân viên kỹ thuật đang hoạt động.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PHIEU_LienKet ON dbo.PHIEU_KHAM_BENH'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HO_SO_BENH_AN h ON h.MaHS=i.MaHS JOIN dbo.LICH_KHAM l ON l.MaLich=i.MaLich WHERE l.MaBN<>h.MaBN OR l.MaPhong<>i.MaPhong OR(i.MaBS IS NOT NULL AND l.MaBS<>i.MaBS))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51033,N''Phiếu tiếp nhận có lịch phải khớp bệnh nhân, phòng và bác sĩ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPhieu=i.MaPhieu WHERE EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaPhieu=i.MaPhieu) AND EXISTS(SELECT i.MaHS,i.MaLich EXCEPT SELECT d.MaHS,d.MaLich))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51034,N''Phiếu đã phát sinh lần khám không đổi hồ sơ/lịch nguồn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PKB_KhoaLoaiKham ON dbo.PHIEU_KHAM_BENH AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N' BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'  SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'  IF UPDATE(MaPhieu) THROW 53401,N''Mã phiếu tiếp nhận là định danh bất biến.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPhieu=i.MaPhieu'+NCHAR(13)+N''+NCHAR(10)+N'   WHERE EXISTS(SELECT i.LoaiKham,i.PhiPhuThuDichVu EXCEPT SELECT d.LoaiKham,d.PhiPhuThuDichVu))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 53401,N''Loại khám và mức phụ thu đã lưu khi tiếp nhận được giữ nguyên.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PN_GhiSo ON dbo.PHIEU_NHAP'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHH FROM dbo.HANG_HOA h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_NHAP c ON c.MaHH=h.MaHH JOIN inserted i ON i.MaPN=c.MaPN;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51020,N''Phiếu nhập đã ghi sổ giữ nguyên.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_NHAP c ON c.MaPN=i.MaPN JOIN dbo.HOA_DON_NHAP h ON h.MaHDN=i.MaHDN JOIN dbo.LO_HANG_HOA l ON l.MaLo=c.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE l.MaHH<>c.MaHH OR l.MaKho<>i.MaKho OR l.MaNCC<>h.MaNCC)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51019,N''Nguồn phiếu nhập phải khớp hàng hóa, kho và nhà cung cấp của các lô chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TongTien<>COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaPN=i.MaPN),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51021,N''Tổng nhập phải bằng chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã ghi sổ'' AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_NHAP c WHERE c.MaPN=i.MaPN))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51022,N''Không ghi sổ phiếu nhập rỗng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_PX_GhiSoDuDon ON dbo.PHIEU_XUAT'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' -- Khóa mặt hàng dùng chung cho nhập/xuất để tránh hai quầy cùng dùng tồn.'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHH FROM dbo.HANG_HOA h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_XUAT c ON c.MaHH=h.MaHH JOIN inserted i ON i.MaPX=c.MaPX;'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=d.MaDT FROM dbo.DON_THUOC d WITH(UPDLOCK,HOLDLOCK) JOIN dbo.CHI_TIET_DON_THUOC ct ON ct.MaDT=d.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTDT=ct.MaCTDT JOIN inserted i ON i.MaPX=x.MaPX;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51025,N''Phiếu xuất đã ghi sổ giữ nguyên; không giảm lượng hoặc cấp lại.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT LEFT JOIN dbo.DON_THUOC d ON d.MaDT=c.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.THUOC t ON t.MaThuoc=c.MaThuoc LEFT JOIN dbo.LO_HANG_HOA l ON l.MaLo=x.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE(i.MaLS IS NOT NULL AND(x.MaCTDT IS NULL OR i.MaLS<>d.MaLS OR x.MaHH<>t.MaHH OR x.MaLo IS NULL))'+NCHAR(13)+N''+NCHAR(10)+N' OR(i.MaLS IS NULL AND x.MaCTDT IS NOT NULL) OR(x.MaLo IS NOT NULL AND(l.MaHH<>x.MaHH OR l.MaKho<>i.MaKho)))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51024,N''Nguồn phiếu xuất phải khớp đơn thuốc, bệnh nhân, lô và kho của mọi chi tiết.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i WHERE i.TrangThai=N''Đã ghi sổ'' AND NOT EXISTS(SELECT 1 FROM dbo.CHI_TIET_PHIEU_XUAT c WHERE c.MaPX=i.MaPX))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51026,N''Không ghi sổ phiếu xuất rỗng.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.CHI_TIET_DON_THUOC c ON c.MaCTDT=x.MaCTDT LEFT JOIN dbo.DON_THUOC d ON d.MaDT=c.MaDT'+NCHAR(13)+N''+NCHAR(10)+N' LEFT JOIN dbo.LO_HANG_HOA l ON l.MaLo=x.MaLo'+NCHAR(13)+N''+NCHAR(10)+N' WHERE i.TrangThai=N''Đã ghi sổ'' AND((x.MaCTDT IS NOT NULL AND(d.TrangThai<>N''Đã xác nhận'' OR d.NgayKe>i.NgayXuat))'+NCHAR(13)+N''+NCHAR(10)+N' OR (x.MaLo IS NOT NULL AND(l.TrangThai<>N''Còn sử dụng'' OR l.NgayNhap>i.NgayXuat OR(l.HanSuDung IS NOT NULL AND l.HanSuDung<CAST(i.NgayXuat AS DATE))))))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51027,N''Đơn chưa xác nhận/ngừng áp dụng hoặc lô không hợp lệ, hết hạn.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' -- Mọi dòng của các đơn đang cấp phải đã xuất đủ trong cùng transaction.'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c WHERE c.MaDT IN'+NCHAR(13)+N''+NCHAR(10)+N' (SELECT ct.MaDT FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX JOIN dbo.CHI_TIET_DON_THUOC ct ON ct.MaCTDT=x.MaCTDT WHERE i.TrangThai=N''Đã ghi sổ'')'+NCHAR(13)+N''+NCHAR(10)+N' AND c.SoLuong<>COALESCE((SELECT SUM(x.SoLuong) FROM dbo.CHI_TIET_PHIEU_XUAT x JOIN dbo.PHIEU_XUAT p ON p.MaPX=x.MaPX WHERE x.MaCTDT=c.MaCTDT AND p.TrangThai=N''Đã ghi sổ''),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51028,N''Phải cấp đủ toàn bộ đơn trong một lần xác nhận; không cấp một phần hoặc cấp lại.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaPX=i.MaPX WHERE i.TrangThai=N''Đã ghi sổ'''+N' AND'+NCHAR(13)+N''+NCHAR(10)+N' COALESCE((SELECT SUM(n.SoLuong) FROM dbo.CHI_TIET_PHIEU_NHAP n JOIN dbo.PHIEU_NHAP p ON p.MaPN=n.MaPN WHERE p.TrangThai=N''Đã ghi sổ'' AND p.MaKho=i.MaKho AND n.MaHH=x.MaHH AND(n.MaLo=x.MaLo OR(n.MaLo IS NULL AND x.MaLo IS NULL))),0)'+NCHAR(13)+N''+NCHAR(10)+N' < COALESCE((SELECT SUM(e.SoLuong) FROM dbo.CHI_TIET_PHIEU_XUAT e JOIN dbo.PHIEU_XUAT p ON p.MaPX=e.MaPX WHERE p.TrangThai=N''Đã ghi sổ'' AND p.MaKho=i.MaKho AND e.MaHH=x.MaHH AND(e.MaLo=x.MaLo OR(e.MaLo IS NULL AND x.MaLo IS NULL))),0))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51029,N''Không đủ tồn kho/lô; rollback toàn bộ lần cấp.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_RHM_DichVu_ChiTrongKham ON dbo.DICH_VU_THUC_HIEN AFTER INSERT,UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS WHERE l.TrangThai<>N''Nháp'') THROW 52234,N''Không thêm/sửa dịch vụ sau khi hoàn tất khám.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.[TR_S3_Audit_BANG_LUONG] ON dbo.[BANG_LUONG] AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @session uniqueidentifier=TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N''RHM.MaPhien''));'+NCHAR(13)+N''+NCHAR(10)+N' IF @session IS NULL RETURN;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @actor nvarchar(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @actor=s.MaTK FROM dbo.PHIEN_DANG_NHAP s WITH(HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.TAI_KHOAN t WITH(HOLDLOCK) ON t.MaTK=s.MaTK'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.NHAN_VIEN n WITH(HOLDLOCK) ON n.MaNV=t.MaNV'+NCHAR(13)+N''+NCHAR(10)+N' WHERE s.MaPhien=@session AND s.TrangThaiPhien=N''Đang mở'''+NCHAR(13)+N''+NCHAR(10)+N' AND s.HoatDongCuoiUtc>=DATEADD(minute,-5,SYSUTCDATETIME())'+NCHAR(13)+N''+NCHAR(10)+N' AND t.TrangThai=N''Đang hoạt động'' AND n.TrangThai=N''Đang làm việc'';'+NCHAR(13)+N''+NCHAR(10)+N' IF @actor IS NULL THROW 53022,N''Không có phiên hợp lệ để ghi audit nghiệp vụ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' '+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @mask varbinary(max)=COLUMNS_UPDATED();'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @changed nvarchar(max)=STUFF((SELECT N'',''+c.name FROM sys.columns c'+NCHAR(13)+N''+NCHAR(10)+N' WHERE c.object_id=OBJECT_ID(N''dbo.BANG_LUONG'')'+NCHAR(13)+N''+NCHAR(10)+N' AND c.name NOT LIKE N''%MatKhau%'' AND c.name NOT LIKE N''%Token%'' AND c.name NOT LIKE N''%Secret%'' AND c.name NOT LIKE N''%ApiKey%'''+NCHAR(13)+N''+NCHAR(10)+N' AND CONVERT(int,SUBSTRING(@mask,(c.column_id-1)/8+1,1)) & CONVERT(int,POWER(2,(c.column_id-1)%8))>0'+NCHAR(13)+N''+NCHAR(10)+N' ORDER BY c.column_id FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,1,N'''');'+NCHAR(13)+N''+NCHAR(10)+N' INSERT dbo.NHAT_KY_THAO_TAC(MaNK,MaTK,ThoiGian,ThoiGianUtc,MaPhien,MaSuKien,PhanHe,HanhDong,LoaiDoiTuong,MaDoiTuong,KetQua,DuLieuTruoc,DuLieuSau)'+NCHAR(13)+N''+NCHAR(10)+N' SELECT N''NK''+CONVERT(nvarchar(36),NEWID()),@actor,SYSDATETIME(),SYSUTCDATETIME(),@session,NEWID(),N''BANG_LUONG'','+NCHAR(13)+N''+NCHAR(10)+N' CASE WHEN NOT EXISTS(SELECT 1 FROM deleted) THEN N''CREATE'' WHEN NOT EXISTS(SELECT 1 FROM inserted) THEN N''CANCEL'' ELSE CASE WHEN i.TrangThai=d.TrangThai THEN N''UPDATE'' WHEN i.TrangThai=N''Đã duyệt'' THEN N''APPROVE'' WHEN i.TrangThai=N''Đã xác nhận'' THEN N''CONFIRM'' WHEN i.TrangThai IN(N''Đã chốt'',N''Đã hoàn thành'') THEN N''FINALIZE'' WHEN i.TrangThai IN(N''Hủy'',N''Đã hủy'') THEN N''CANCEL'' WHEN i.TrangThai IN(N''Khóa'',N''Đã khóa'') THEN N''LOCK'' ELSE N''UPDATE'' END END,'+NCHAR(13)+N''+NCHAR(10)+N' N''BANG_LUONG'',CASE WHEN LEN(COALESCE(CONVERT(nvarchar(100),i.[MaBL]),CONVERT(nvarchar(100),d.[MaBL])))>50 THEN LEFT(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',COALESCE(CONVERT(nvarchar(100),i.[MaBL]),CONVERT(nvarchar(100),d.[MaBL]))),2),50) ELSE COALESCE(CONVERT(nvarchar(100),i.[MaBL]),CONVERT(nvarchar(100),d.[MaBL])) END,N''Thành công'','+NCHAR(13)+N''+NCHAR(10)+N' (SELECT d.[MaBL],d.TrangThai,@changed AS TruongDaDoi FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),'+NCHAR(13)+N''+NCHAR(10)+N' (SELECT i.[MaBL],i.TrangThai,@changed AS TruongDaDoi FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)'+NCHAR(13)+N''+NCHAR(10)+N' FROM inserted i FULL JOIN deleted d ON i.[MaBL]=d.[MaBL];'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.[TR_S3_Audit_CA_LAM] ON dbo.[CA_LAM] AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @session uniqueidentifier=TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N''RHM.MaPhien''));'+NCHAR(13)+N''+NCHAR(10)+N' IF @session IS NULL RETURN;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @actor nvarchar(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @actor=s.MaTK FROM dbo.PHIEN_DANG_NHAP s WITH(HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.TAI_KHOAN t WITH(HOLDLOCK) ON t.MaTK=s.MaTK'+NCHAR(13)+N''+NCHAR(10)+N' JOIN dbo.NHAN_VIEN n WITH(HOLDLOCK) ON n.MaNV=t.MaNV'+NCHAR(13)+N''+NCHAR(10)+N' WHERE s.MaPhien=@session AND s.TrangThaiPhien=N''Đang mở'''+NCHAR(13)+N''+NCHAR(10)+N' AND s.HoatDongCuoiUtc>=DATEADD(minute,-5,SYSUTCDATETIME())'+NCHAR(13)+N''+NCHAR(10)+N' AND t.TrangThai=N''Đang hoạt động'' AND n.TrangThai=N''Đang làm việc'';'+NCHAR(13)+N''+NCHAR(10)+N' IF @actor IS NULL THROW 53022,N''Không có phiên hợp lệ để ghi audit nghiệp vụ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' '+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @mask varbinary(max)=COLUMNS_UPDATED();'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @changed nvarchar(max)=STUFF((SELECT N'',''+c.name FROM sys.columns c'+NCHAR(13)+N''+NCHAR(10)+N' WHERE c.object_id=OBJECT_ID(N''dbo.CA_LAM'')'+NCHAR(13)+N''+NCHAR(10)+N' AND c.name NOT LIKE N''%MatKhau%'' AND c.name NOT LIKE N''%Token%'' AND c.name NOT LIKE N''%Secret%'' AND c.name NOT LIKE N''%ApiKey%'''+NCHAR(13)+N''+NCHAR(10)+N' AND CONVERT(int,SUBSTRING(@mask,(c.column_id-1)/8+1,1)) & CONVERT(int,POWER(2,(c.column_id-1)%8))>0'+NCHAR(13)+N''+NCHAR(10)+N' ORDER BY c.column_id FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,1,N'''');'+NCHAR(13)+N''+NCHAR(10)+N' INSERT dbo.NHAT_KY_THAO_TAC(MaNK,MaTK,ThoiGian,ThoiGianUtc,MaPhien,MaSuKien,PhanHe,HanhDong,LoaiDoiTuong,MaDoiTuong,KetQua,DuLieuTruoc,DuLieuSau)'+NCHAR(13)+N''+NCHAR(10)+N' SELECT N''N