LieuSau)'+NCHAR(13)+N''+NCHAR(10)+N' SELECT N''NK''+CONVERT(nvarchar(36),NEWID()),@actor,SYSDATETIME(),SYSUTCDATETIME(),@session,NEWID(),N''XAC_NHAN_DOI_LICH_KHAM'','+NCHAR(13)+N''+NCHAR(10)+N' CASE WHEN NOT EXISTS(SELECT 1 FROM deleted) THEN N''CREATE'' WHEN NOT EXISTS(SELECT 1 FROM inserted) THEN N''CANCEL'' ELSE CASE WHEN i.TrangThai=d.TrangThai THEN N''UPDATE'' WHEN i.TrangThai=N''Đã duyệt'' THEN N''APPROVE'' WHEN i.TrangThai=N''Đã xác nhận'' THEN N''CONFIRM'' WHEN i.TrangThai IN(N''Đã chốt'',N''Đã hoàn thành'') THEN N''FINALIZE'' WHEN i.TrangThai IN(N''Hủy'',N''Đã hủy'') THEN N''CANCEL'' WHEN i.TrangThai IN(N''Khóa'',N''Đã khóa'') THEN N''LOCK'' ELSE N''UPDATE'' END END,'+NCHAR(13)+N''+NCHAR(10)+N' N''XAC_NHAN_DOI_LICH_KHAM'',CASE WHEN LEN(COALESCE(CONVERT(nvarchar(100),i.[MaDonNghi]),CONVERT(nvarchar(100),d.[MaDonNghi]))+N''/''+COALESCE(CONVERT(nvarchar(100),i.[MaLich]),CONVERT(nvarchar(100),d.[MaLich])))>50 THEN LEFT(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',COALESCE(CONVERT(nvarchar(100),i.[MaDonNghi]),CONVERT(nvarchar(100),d.[MaDonNghi]))+N''/''+COALESCE(CONVERT(nvarchar(100),i.[MaLich]),CONVERT(nvarchar(100),d.[MaLich]))),2),50) ELSE COALESCE(CONVERT(nvarchar(100),i.[MaDonNghi]),CONVERT(nvarchar(100),d.[MaDonNghi]))+N''/''+COALESCE(CONVERT(nvarchar(100),i.[MaLich]),CONVERT(nvarchar(100),d.[MaLich])) END,N''Thành công'','+NCHAR(13)+N''+NCHAR(10)+N' (SELECT d.[MaDonNghi],d.[MaLich],d.TrangThai,@changed AS TruongDaDoi FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),'+NCHAR(13)+N''+NCHAR(10)+N' (SELECT i.[MaDonNghi],i.[MaLich],i.TrangThai'+N',@changed AS TruongDaDoi FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)'+NCHAR(13)+N''+NCHAR(10)+N' FROM inserted i FULL JOIN deleted d ON i.[MaDonNghi]=d.[MaDonNghi] AND i.[MaLich]=d.[MaLich];'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_TB_Serial_BaoVe ON dbo.THIET_BI'+NCHAR(13)+N''+NCHAR(10)+N' AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N' BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'  SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE(i.SoSerial<>d.SoSerial OR i.MaHH<>d.MaHH) AND EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52606,N''Thiết bị đã có lịch sử bảo trì; không đổi serial hoặc nguồn hàng hóa.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE d.TinhTrang=N''Ngưng sử dụng'' AND i.TinhTrang<>d.TinhTrang)'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52606,N''Thiết bị đã ngưng sử dụng không được tự khôi phục.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i WHERE i.TinhTrang=N''Đang bảo trì'' AND NOT EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND b.TrangThai=N''Đang thực hiện''))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52606,N''Tình trạng Đang bảo trì chỉ được đặt khi thực hiện phiếu bảo trì.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i WHERE EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND('+NCHAR(13)+N''+NCHAR(10)+N'   (b.TrangThai=N''Đang thực hiện'' AND i.TinhTrang<>N''Đang bảo trì'') OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'') AND i.TinhTrang<>N''Hư hại'')'+NCHAR(13)+N''+NCHAR(10)+N'   OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND i.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')))))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52606,N''Thiết bị đang có phiếu mở; cập nhật tình trạng qua Lịch sử bảo trì.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_TB_ThanhLy_BaoVe ON dbo.THIET_BI'+NCHAR(13)+N''+NCHAR(10)+N' AFTER INSERT,UPDATE,DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N' BEGIN'+NCHAR(13)+N''+NCHAR(10)+N'  SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM deleted WHERE NgayThanhLy IS NOT NULL)'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52610,N''Thiết bị đã thanh lý: giữ nguyên hồ sơ, không sửa, xóa hoặc khôi phục.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaTB=i.MaTB WHERE i.NgayThanhLy IS NOT NULL AND'+NCHAR(13)+N''+NCHAR(10)+N'   (d.MaTB IS NULL OR d.TinhTrang<>N''Hư hại'' OR d.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')'+NCHAR(13)+N''+NCHAR(10)+N'    OR EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(UPDLOCK,HOLDLOCK) WHERE b.MaTB=i.MaTB AND b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện''))))'+NCHAR(13)+N''+NCHAR(10)+N'   THROW 52610,N''Chỉ thanh lý thiết bị hư hại chưa ngưng sử dụng và không có phiếu bảo trì mở.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_THUOC_KhoaHangHoa ON dbo.THUOC'+NCHAR(13)+N''+NCHAR(10)+N'AFTER UPDATE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaThuoc=i.MaThuoc WHERE i.MaHH<>d.MaHH AND EXISTS(SELECT 1 FROM dbo.CHI_TIET_DON_THUOC c WHERE c.MaThuoc=i.MaThuoc))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51032,N''Thuốc đã kê đơn không đổi hàng hóa nguồn; DonGiaBan hiện hành vẫn được cập nhật.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'CREATE   TRIGGER dbo.TR_TT_KiemTraSoDu ON dbo.THANH_TOAN'+NCHAR(13)+N''+NCHAR(10)+N'AFTER INSERT, UPDATE, DELETE AS'+NCHAR(13)+N''+NCHAR(10)+N'BEGIN'+NCHAR(13)+N''+NCHAR(10)+N' SET NOCOUNT ON;'+NCHAR(13)+N''+NCHAR(10)+N' DECLARE @Lock NVARCHAR(50);'+NCHAR(13)+N''+NCHAR(10)+N' SELECT @Lock=h.MaHD FROM dbo.HOA_DON h WITH(UPDLOCK,HOLDLOCK)'+NCHAR(13)+N''+NCHAR(10)+N' WHERE h.MaHD IN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted);'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM deleted WHERE TrangThai=N''Đã xác nhận'')'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51009,N''Giao dịch đã xác nhận không sửa/xóa; lập giao dịch điều chỉnh mới.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD WHERE i.TrangThai=N''Đã xác nhận'' AND(h.TrangThai<>N''Đã xác nhận'' OR i.NgayThanhToan<h.NgayXacNhan))'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51010,N''Chỉ thu/hoàn sau khi hóa đơn đã xác nhận.'',1;'+NCHAR(13)+N''+NCHAR(10)+N' IF EXISTS(SELECT 1 FROM dbo.HOA_DON h JOIN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted) z ON z.MaHD=h.MaHD'+NCHAR(13)+N''+NCHAR(10)+N' OUTER APPLY(SELECT SUM(CASE WHEN t.LoaiGiaoDich=N''Thu'' THEN t.SoTien ELSE -t.SoTien END) ThuRong FROM dbo.THANH_TOAN t WHERE t.MaHD=h.MaHD AND t.TrangThai=N''Đã xác nhận'') a'+NCHAR(13)+N''+NCHAR(10)+N' WHERE COALESCE(a.ThuRong,0)<0 OR COALESCE(a.ThuRong,0)>h.SoTienPhaiThu)'+NCHAR(13)+N''+NCHAR(10)+N'  THROW 51011,N''Thu vượt tiền phải trả hoặc hoàn vượt tiền đang giữ.'',1;'+NCHAR(13)+N''+NCHAR(10)+N'END;'; EXEC sys.sp_executesql @RhmSnapshotSql;
 SET @RhmSnapshotSql=CAST(N'' AS nvarchar(max))+N'EXEC sys.sp_addextendedproperty @name=N''RHM.AcademicData.Version'',@value=1;'; EXEC sys.sp_executesql @RhmSnapshotSql;
