    [DiUng] NVARCHAR(MAX) NULL,
    [TrangThai] NVARCHAR(50) NOT NULL
);

-- 02. HO_SO_BENH_AN
CREATE TABLE [dbo].[HO_SO_BENH_AN] (
    [MaHS] NVARCHAR(50) NOT NULL CONSTRAINT [PK_HO_SO_BENH_AN] PRIMARY KEY,
