EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.[TR_CW_Audit_CAU_HINH_THUOC_KE_DON] ON dbo.[CAU_HINH_THUOC_KE_DON] AFTER INSERT,UPDATE,DELETE AS
