    CONSTRAINT [CK_CHAM_CONG_3] CHECK (([TrangThai]=N''Đã xác nhận'' AND [MaNVDoiSoat] IS NOT NULL AND [NgayDoiSoat] IS NOT NULL) OR [TrangThai]<>N''Đã xác nhận'')
);';
 IF OBJECT_ID(N'dbo.CHI_TIET_LUONG',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[CHI_TIET_LUONG] (
    [MaCTL] NVARCHAR(50) NOT NULL CONSTRAINT [PK_CHI_TIET_LUONG] PRIMARY KEY,
