    CONSTRAINT [CK_CTL_3] CHECK (LEN(LTRIM(RTRIM([LyDo])))>0)
);';
 IF OBJECT_ID(N'dbo.PHU_TA_DICH_VU',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[PHU_TA_DICH_VU] (
    [MaPTDV] NVARCHAR(50) NOT NULL CONSTRAINT [PK_PHU_TA_DICH_VU] PRIMARY KEY,
