    CONSTRAINT [UQ_PHU_TA_DV] UNIQUE ([MaDVThucHien],[MaNV]),
    CONSTRAINT [CK_PHU_TA_DV_TT] CHECK ([TrangThai] IN (N''Đã xác nhận'',N''Hủy''))
