 IF OBJECT_ID(N'dbo.CHI_TIET_HOA_HONG_LUONG',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[CHI_TIET_HOA_HONG_LUONG] (
