 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'TyLeBHYT') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [TyLeBHYT] decimal(9,6) NOT NULL CONSTRAINT DF_CSL_BHYT DEFAULT(0.015);';
 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'TyLeBHTN') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [TyLeBHTN] decimal(9,6) NOT NULL CONSTRAINT DF_CSL_BHTN DEFAULT(0.01);';
 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'HeSoTangCaThuong') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [HeSoTangCaThuong] decimal(4,2) NOT NULL CONSTRAINT DF_CSL_OTThuong DEFAULT(1.50);';
 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'HeSoTangCaChuNhat') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [HeSoTangCaChuNhat] decimal(4,2) NOT NULL CONSTRAINT DF_CSL_OTChuNhat DEFAULT(2.00);';
 IF COL_LENGTH(N'dbo.CHINH_SACH_LUONG',N'HeSoTangCaNgayLe') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.CHINH_SACH_LUONG ADD [HeSoTangCaNgayLe] decimal(4,2) NOT NULL CONSTRAINT DF_CSL_OTNgayLe DEFAULT(3.00);';
 IF OBJECT_ID(N'dbo.CK_CHINH_SACH_LUONG_6') IS NULL
 EXEC sys.sp_executesql N'ALTER TABLE dbo.[CHINH_SACH_LUONG] WITH CHECK ADD CONSTRAINT [CK_CHINH_SACH_LUONG_6] CHECK(PhuCapCoDinh>=0 AND TyLeBHXH BETWEEN 0 AND 1 AND TyLeBHYT BETWEEN 0 AND 1 AND TyLeBHTN BETWEEN 0 AND 1);';
 IF OBJECT_ID(N'dbo.CK_CHINH_SACH_LUONG_7') IS NULL
