 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraDongBoV9 AS
BEGIN
 SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''RHM.SqlV9.Version'' AND TRY_CONVERT(int,value)=9)
  THROW 52335,N''Chưa hoàn tất hợp nhất SQL V9; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
 DECLARE @cols TABLE(T sysname,C sysname,Ty sysname,L smallint,P tinyint,S tinyint,N bit);
 INSERT @cols VALUES(N''NGAY_NGHI_LE'',N''MaNgayNghi'',N''nvarchar'',100,0,0,0),
(N''NGAY_NGHI_LE'',N''NgayNghi'',N''date'',3,0,0,0),
(N''NGAY_NGHI_LE'',N''TenNgayNghi'',N''nvarchar'',510,0,0,0),
(N''NGAY_NGHI_LE'',N''LoaiNgayNghi'',N''nvarchar'',100,0,0,0),
(N''NGAY_NGHI_LE'',N''CoHuongLuong'',N''bit'',1,0,0,0),
(N''NGAY_NGHI_LE'',N''GhiChu'',N''nvarchar'',1000,0,0,1),
(N''CHAM_CONG'',N''MaCC'',N''nvarchar'',100,0,0,0),
(N''CHAM_CONG'',N''MaLLV'',N''nvarchar'',100,0,0,0),
(N''CHAM_CONG'',N''SoPhutDiTre'',N''int'',4,0,0,0),
(N''CHAM_CONG'',N''CongDuocTinh'',N''decimal'',5,4,2,0),
(N''CHAM_CONG'',N''TrangThai'',N''nvarchar'',100,0,0,0),
(N''CHAM_CONG'',N''MaNVDoiSoat'',N''nvarchar'',100,0,0,1),
(N''CHAM_CONG'',N''NgayDoiSoat'',N''datetime2'',6,0,0,1),
(N''CHAM_CONG'',N''GhiChu'',N''nvarchar'',-1,0,0,1),
(N''CHI_TIET_LUONG'',N''MaCTL'',N''nvarchar'',100,0,0,0),
(N''CHI_TIET_LUONG'',N''MaBL'',N''nvarchar'',100,0,0,0),
(N''CHI_TIET_LUONG'',N''LoaiKhoan'',N''nvarchar'',100,0,0,0),
(N''CHI_TIET_LUONG'',N''TinhChat'',N''nvarchar'',20,0,0,0),
(N''CHI_TIET_LUONG'',N''SoTien'',N''decimal'',9,18,2,0),
(N''CHI_TIET_LUONG'',N''NgayPhatSinh'',N''date'',3,0,0,0),
(N''CHI_TIET_LUONG'',N''LyDo'',N''nvarchar'',1000,0,0,0),
(N''CHI_TIET_LUONG'',N''MaNVDuyet'',N''nvarchar'',100,0,0,1),
(N''PHU_TA_DICH_VU'',N''MaPTDV'',N''nvarchar'',100,0,0,0),
(N''PHU_TA_DICH_VU'',N''MaDVThucHien'',N''nvarchar'',100,0,0,0),
(N''PHU_TA_DICH_VU'',N''MaNV'',N''nvarchar'',100,0,0,0),
(N''PHU_TA_DICH_VU'',N''TrangThai'',N''nvarchar'',100,0,0,0),
