(N''NHAT_KY_DUYET_CHAM_CONG'',N''LyDo'',N''nvarchar'',1000,0,0,0);
 IF EXISTS(SELECT 1 FROM (VALUES
(N''PK_NGAY_NGHI_LE'',N''PK''),
(N''UQ_NGAY_NGHI_LE_NgayNghi'',N''UQ''),
(N''DF_NNL_HuongLuong'',N''D''),
(N''CK_NGAY_NGHI_LE_Loai'',N''C''),
(N''PK_CHAM_CONG'',N''PK''),
(N''UQ_CHAM_CONG_Lich'',N''UQ''),
(N''DF_CC_DiTre'',N''D''),
(N''DF_CC_Cong'',N''D''),
(N''CK_CHAM_CONG_1'',N''C''),
(N''CK_CHAM_CONG_2'',N''C''),
(N''CK_CHAM_CONG_3'',N''C''),
(N''PK_CHI_TIET_LUONG'',N''PK''),
(N''CK_CTL_1'',N''C''),
(N''CK_CTL_2'',N''C''),
(N''CK_CTL_3'',N''C''),
(N''PK_PHU_TA_DICH_VU'',N''PK''),
(N''UQ_PHU_TA_DV'',N''UQ''),
(N''CK_PHU_TA_DV_TT'',N''C''),
(N''PK_CHI_TIET_HOA_HONG_LUONG'',N''PK''),
(N''CK_CTHH_1'',N''C''),
(N''CK_CTHH_2'',N''C''),
(N''UQ_CTHH_Luong_DichVu'',N''UQ''),
(N''PK_LAM_THEM_GIO'',N''PK''),
(N''CK_LTG_1'',N''C''),
(N''CK_LTG_2'',N''C''),
(N''CK_LTG_3'',N''C''),
(N''PK_NHAT_KY_DUYET_CHAM_CONG'',N''PK'')) required(N,T) WHERE OBJECT_ID(N''dbo.''+required.N,required.T) IS NULL)
  THROW 52335,N''Thiếu PK/UNIQUE/CHECK/DEFAULT của các bảng V9.'',1;
 IF EXISTS(SELECT 1 FROM @cols e LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.''+e.T) AND c.name=e.C
  LEFT JOIN sys.types t ON t.user_type_id=c.user_type_id WHERE c.column_id IS NULL OR t.name<>e.Ty OR c.max_length<>e.L OR c.is_nullable<>e.N
  OR (e.Ty=N''decimal'' AND(c.precision<>e.P OR c.scale<>e.S)) OR(e.Ty=N''datetime2'' AND c.scale<>e.S))
  THROW 52335,N''Thiếu hoặc sai kiểu cột lịch khám/chấm công/lương V9.'',1;
 IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0 AND name NOT IN(N''PHIEN_DANG_NHAP'',N''PHAN_QUYEN_VAI_TRO'',N''ANH_XQUANG_LAN_KHAM'',N''PHAN_CONG_ANH_XQUANG''))<>60
  THROW 52335,N''Schema hợp nhất phải có đủ 60 bảng.'',1;
 IF NOT EXISTS(SELECT 1 FROM sys.computed_columns WHERE object_id=OBJECT_ID(N''dbo.BANG_LUONG'') AND name=N''LuongTheoCa'' AND is_persisted=1 AND definition LIKE N''%PhienBanTinhLuong%'' AND definition LIKE N''%LuongTheoCaTruocDongBo%'' AND definition LIKE N''%CongThucTe%'')
 OR NOT EXISTS(SELECT 1 FROM sys.computed_columns WHERE object_id=OBJECT_ID(N''dbo.BANG_LUONG'') AND name=N''TongLuong'' AND is_persisted=1 AND definition LIKE N''%TongLuongTruocDongBo%'' AND definition LIKE N''%TienBaoHiem%'')
  THROW 52335,N''Công thức lương không giữ bản tiền cũ hoặc chưa dùng V9.'',1;
 IF EXISTS(SELECT 1 FROM (VALUES
 (N''TR_BL_ChotLuong'',N''TR''),(N''TR_CTL_KhoaTheoBangLuong'',N''TR''),(N''TR_CTHH_KhoaTheoBangLuong'',N''TR''),
 (N''TR_NKCC_KhongSua'',N''TR''),(N''TR_CC_KhoaKyDaChot'',N''TR''),(N''TR_LLV_KhoaKyDaChot'',N''TR''),
 (N''RHM_TinhLuongKy'',N''P''),(N''RHM_ChotLuongNhanVien'',N''P''),(N''VW_CONG_CHUAN_BANG_LUONG'',N''V''),(N''VW_DICH_VU_DU_HOA_HONG'',N''V''),
 (N''CK_BL_PhienBan'',N''C''),(N''CK_BANG_LUONG_1'',N''C''),(N''CK_BANG_LUONG_2'',N''C''),(N''CK_BANG_LUONG_3'',N''C''),(N''CK_BANG_LUONG_4'',N''C''),(N''CK_BANG_LUONG_5'',N''C''),
 (N''CK_CHINH_SACH_LUONG_6'',N''C''),(N''CK_CHINH_SACH_LUONG_7'',N''C''),(N''CK_LICH_KHAM_MucDoNghiemTrong'',N''C''),(N''FK_LICH_KHAM_BacSiDuBi'',N''F''),
 (N''FK_BL_NguoiChot'',N''F''),(N''FK_CC_MaLLV'',N''F''),(N''FK_CC_NguoiDoiSoat'',N''F''),(N''FK_CTL_BangLuong'',N''F''),(N''FK_CTL_NguoiDuyet'',N''F''),
 (N''FK_PTDV_DVTH'',N''F''),(N''FK_PTDV_NV'',N''F''),(N''FK_CTHH_BL'',N''F''),(N''FK_CTHH_CTHD'',N''F''),(N''FK_LTG_NV'',N''F''),(N''FK_LTG_NguoiDuyet'',N''F''),
 (N''FK_NKCC_Lich'',N''F''),(N''FK_NKCC_NhanVien'',N''F''),(N''FK_NKCC_NguoiDuyet'',N''F''),(N''UQ_BANG_LUONG_NhanVien_Ky'',N''UQ'')) o(N,T)
 WHERE OBJECT_ID(N''dbo.''+o.N,o.T) IS NULL)
  THROW 52335,N''Thiếu đối tượng/ràng buộc SQL V9.'',1;
 IF EXISTS(SELECT 1 FROM (VALUES(N''NGAY_NGHI_LE'',N''IX_NNL_Ngay''),(N''CHI_TIET_LUONG'',N''IX_CTL_BangLuong''),(N''CHI_TIET_HOA_HONG_LUONG'',N''IX_CTHH_BangLuong''),(N''LAM_THEM_GIO'',N''IX_LTG_NV_Ngay''),(N''NHAT_KY_DUYET_CHAM_CONG'',N''IX_NKCC_Lich_Ngay'')) e(T,N)
  LEFT JOIN sys.indexes i ON i.object_id=OBJECT_ID(N''dbo.''+e.T) AND i.name=e.N WHERE i.index_id IS NULL OR i.is_disabled=1 OR i.is_hypothetical=1)
  THROW 52335,N''Thiếu hoặc tắt index SQL V9.'',1;
 IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1)
 OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1)
 OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_class=1 AND is_disabled=1)
  THROW 52335,N''Có ràng buộc chưa trusted hoặc trigger bị tắt.'',1;
 SELECT N''SqlV9Merged'' SchemaVersion,(SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0) TableCount,
 (SELECT COUNT(*) FROM dbo.BANG_LUONG WHERE PhienBanTinhLuong=8) PreservedLegacyPayroll;
END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraSchema AS
BEGIN
 SET NOCOUNT ON;
 EXEC dbo.usp_RHM_KiemTraSchemaNen;
 EXEC dbo.usp_RHM_KiemTraKeThuoc;
 EXEC dbo.usp_RHM_KiemTraDongBoV9;
END;';
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.SqlV9.Version')
  EXEC sys.sp_updateextendedproperty @name=N'RHM.SqlV9.Version',@value=9;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.SqlV9.Version',@value=9;
 EXEC dbo.usp_RHM_KiemTraSchema;
 COMMIT TRANSACTION;
 EXEC sys.sp_set_session_context @key=N'RHM.SqlV9.Completed',@value=1;
 PRINT N'HOÀN TẤT: 60 bảng, lịch khám, chấm công, lương V9 và quy trình khám/thu tiền đã đồng bộ.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO

-- PHA 6: BẢO TRÌ ĐÚNG THIẾT BỊ/SERIAL. Chỉ thay đổi hai bảng thiết bị/bảo trì.
SET XACT_ABORT ON;
EXEC sys.sp_set_session_context @key=N'RHM.MaintenanceSerial.Completed',@value=0;
BEGIN TRY
 IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.SqlV9.Completed')),0)<>1
  THROW 52600,N'Phải hoàn tất các pha trước khi đồng bộ bảo trì theo serial.',1;
 BEGIN TRANSACTION;
 DECLARE @maintenanceInstalled bit=CASE WHEN EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.MaintenanceSerial.Version' AND TRY_CONVERT(int,value)=1) THEN 1 ELSE 0 END;
 IF COL_LENGTH(N'dbo.BAO_TRI_THIET_BI',N'NgayXacNhan') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI ADD NgayXacNhan datetime2(0) NULL;
 IF COL_LENGTH(N'dbo.BAO_TRI_THIET_BI',N'NgayThucHien') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI ADD NgayThucHien datetime2(0) NULL;
 IF @maintenanceInstalled=0
 BEGIN
  -- Ngày đã kết thúc trong dữ liệu cũ giữ nguyên; không suy đoán thời điểm xác nhận/thực hiện chưa được lưu.
  EXEC sys.sp_executesql N'
  IF EXISTS(SELECT 1 FROM dbo.THIET_BI WHERE NULLIF(LTRIM(RTRIM(SoSerial)),N'''') IS NULL)
   THROW 52601,N''Có thiết bị thiếu serial; cần nhập serial thật trước khi nâng cấp.'',1;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai NOT IN(N''Nháp'',N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'',N''Hoàn thành'',N''Đã hoàn thành'',N''Hủy''))
   THROW 52601,N''Có trạng thái bảo trì cũ chưa xác định; cần đối chiếu, không tự xóa lịch sử.'',1;
  UPDATE dbo.BAO_TRI_THIET_BI SET TrangThai=CASE
   WHEN TrangThai=N''Nháp'' THEN N''Chưa xác nhận''
   WHEN TrangThai=N''Hoàn thành'' OR(TrangThai=N''Đã xác nhận'' AND NgayKetThuc IS NOT NULL) THEN N''Đã hoàn thành'' ELSE TrangThai END;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai=N''Đã hoàn thành'' AND NgayKetThuc IS NULL)
   THROW 52601,N''Phiếu hoàn thành cũ thiếu ngày kết thúc; cần đối chiếu trước khi nâng cấp.'',1;
  -- Ngày kết thúc của nháp/lần đang làm cũ có thể là lịch dự kiến: giữ lại trong ghi chú trước khi dùng trường này cho kết quả thực tế.
  UPDATE dbo.BAO_TRI_THIET_BI SET GhiChu=CONCAT(GhiChu,N'' | Ngày kết thúc dự kiến trước đồng bộ: '',CONVERT(nvarchar(30),NgayKetThuc,126)),NgayKetThuc=NULL
   WHERE TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND NgayKetThuc IS NOT NULL;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI WHERE TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') GROUP BY MaTB HAVING COUNT(*)>1)
   THROW 52601,N''Một serial có nhiều phiếu đang mở; cần đối chiếu, không tự hủy phiếu.'',1;
  IF EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b JOIN dbo.THIET_BI t ON t.MaTB=b.MaTB
   WHERE b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND(t.TinhTrang IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'') OR t.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')))
   THROW 52601,N''Thiết bị đã ngưng còn phiếu mở; cần đối chiếu trước khi nâng cấp.'',1;
  UPDATE dbo.THIET_BI SET TinhTrang=CASE
   WHEN TinhTrang IN(N''Tốt'',N''Bình thường'',N''Hoạt động tốt'') THEN N''Đang hoạt động''
   WHEN TinhTrang IN(N''Hỏng'',N''Cần bảo trì'') THEN N''Hư hại''
   WHEN TinhTrang=N''Ngừng sử dụng'' THEN N''Ngưng sử dụng'' ELSE TinhTrang END;
  UPDATE t SET TinhTrang=CASE WHEN EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai=N''Đang thực hiện'') THEN N''Đang bảo trì'' ELSE N''Hư hại'' END
   FROM dbo.THIET_BI t WHERE EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện''));
  UPDATE t SET TinhTrang=N''Hư hại'' FROM dbo.THIET_BI t WHERE t.TinhTrang=N''Đang bảo trì''
   AND NOT EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WHERE b.MaTB=t.MaTB AND b.TrangThai=N''Đang thực hiện'');
  IF EXISTS(SELECT 1 FROM dbo.THIET_BI WHERE TinhTrang NOT IN(N''Đang hoạt động'',N''Hư hại'',N''Đang bảo trì'',N''Ngưng sử dụng''))
   THROW 52601,N''Có tình trạng thiết bị chưa xác định; cần đối chiếu thay vì tự đổi dữ liệu.'',1;
  ';
 END;
 IF OBJECT_ID(N'dbo.CK_TB_Serial_KhongTrong',N'C') IS NULL
  ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT CK_TB_Serial_KhongTrong CHECK(NULLIF(LTRIM(RTRIM(SoSerial)),N'') IS NOT NULL);
 IF OBJECT_ID(N'dbo.CK_TB_TinhTrang_BaoTri',N'C') IS NULL
  ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT CK_TB_TinhTrang_BaoTri CHECK(TinhTrang IN(N'Đang hoạt động',N'Hư hại',N'Đang bảo trì',N'Ngưng sử dụng'));
 IF OBJECT_ID(N'dbo.CK_BT_VongDoi',N'C') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI WITH CHECK ADD CONSTRAINT CK_BT_VongDoi CHECK(TrangThai IN(N'Chưa xác nhận',N'Đã xác nhận',N'Đang thực hiện',N'Đã hoàn thành',N'Hủy'));
 IF OBJECT_ID(N'dbo.CK_BT_NoiDung',N'C') IS NULL
  ALTER TABLE dbo.BAO_TRI_THIET_BI WITH CHECK ADD CONSTRAINT CK_BT_NoiDung CHECK(LEN(LTRIM(RTRIM(NoiDung)))>0);
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.BAO_TRI_THIET_BI') AND name=N'UX_BT_Serial_PhieuMo')
  CREATE UNIQUE INDEX UX_BT_Serial_PhieuMo ON dbo.BAO_TRI_THIET_BI(MaTB) WHERE TrangThai IN(N'Chưa xác nhận',N'Đã xác nhận',N'Đang thực hiện');
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_BT_Serial_VongDoi ON dbo.BAO_TRI_THIET_BI
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF TRIGGER_NESTLEVEL(OBJECT_ID(N''dbo.TR_BT_Serial_VongDoi''))>1 RETURN;
  IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaBT=d.MaBT WHERE i.MaBT IS NULL)
   THROW 52602,N''Không xóa lịch sử bảo trì; chỉ hủy phiếu Chưa xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaBT=i.MaBT WHERE d.MaBT IS NULL AND i.TrangThai NOT IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện''))
   THROW 52603,N''Phiếu mới chỉ được lưu Chưa xác nhận hoặc Đang thực hiện.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE d.TrangThai IN(N''Đã hoàn thành'',N''Hủy''))
   THROW 52604,N''Phiếu đã hoàn thành hoặc hủy chỉ được xem.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE i.MaTB<>d.MaTB)
   THROW 52604,N''Không chuyển phiếu sang thiết bị/serial khác.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE d.TrangThai<>N''Chưa xác nhận'' AND EXISTS(
   SELECT i.MaNV,i.NgayBatDau,i.NoiDung,i.ChiPhi,i.NgayBaoTriTiepTheo,i.GhiChu EXCEPT SELECT d.MaNV,d.NgayBatDau,d.NoiDung,d.ChiPhi,d.NgayBaoTriTiepTheo,d.GhiChu))
   THROW 52604,N''Không sửa nội dung phiếu đã xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE i.TrangThai<>d.TrangThai AND NOT(
   (d.TrangThai=N''Chưa xác nhận'' AND i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'',N''Hủy''))
   OR(d.TrangThai=N''Đã xác nhận'' AND i.TrangThai=N''Đang thực hiện'')
   OR(d.TrangThai=N''Đang thực hiện'' AND i.TrangThai=N''Đã hoàn thành'')))
   THROW 52603,N''Chuyển trạng thái bảo trì không đúng vòng đời.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaBT=i.MaBT WHERE EXISTS(SELECT i.NgayXacNhan,i.NgayThucHien,i.NgayKetThuc EXCEPT SELECT d.NgayXacNhan,d.NgayThucHien,d.NgayKetThuc))
   THROW 52604,N''Các thời điểm xác nhận, thực hiện và kết thúc do hệ thống ghi.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaBT=i.MaBT WHERE d.MaBT IS NULL AND(i.NgayXacNhan IS NOT NULL OR i.NgayThucHien IS NOT NULL OR i.NgayKetThuc IS NOT NULL))
   THROW 52604,N''Không tự nhập thời điểm kết thúc hoặc xác nhận phiếu mới.'',1;
  DECLARE @locked int;
  SELECT @locked=COUNT(*) FROM dbo.THIET_BI t WITH(UPDLOCK,HOLDLOCK) JOIN inserted i ON i.MaTB=t.MaTB;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.THIET_BI t ON t.MaTB=i.MaTB LEFT JOIN deleted d ON d.MaBT=i.MaBT
   WHERE (d.MaBT IS NULL OR d.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'')) AND i.TrangThai<>N''Hủy''
    AND(t.TinhTrang<>N''Hư hại'' OR t.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'') OR NULLIF(LTRIM(RTRIM(t.SoSerial)),N'''') IS NULL))
   THROW 52605,N''Chỉ lập/xác nhận/bắt đầu bảo trì serial đang Hư hại và chưa ngưng sử dụng.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaBT=i.MaBT WHERE i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'') AND(d.MaBT IS NULL OR d.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'')) AND i.NgayBatDau>CONVERT(date,SYSDATETIME()))
   THROW 52605,N''Chưa đến ngày dự kiến bắt đầu bảo trì.'',1;
  DECLARE @now datetime2(0)=SYSDATETIME();
  UPDATE b SET
   TrangThai=CASE WHEN i.TrangThai=N''Đã xác nhận'' THEN N''Đang thực hiện'' ELSE i.TrangThai END,
   NgayXacNhan=CASE WHEN i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'') AND(d.MaBT IS NULL OR d.TrangThai=N''Chưa xác nhận'') THEN @now ELSE b.NgayXacNhan END,
   NgayThucHien=CASE WHEN i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'') AND(d.MaBT IS NULL OR d.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'')) THEN @now ELSE b.NgayThucHien END,
   NgayKetThuc=CASE WHEN i.TrangThai=N''Đã hoàn thành'' AND d.TrangThai=N''Đang thực hiện'' THEN @now ELSE b.NgayKetThuc END
   FROM dbo.BAO_TRI_THIET_BI b JOIN inserted i ON i.MaBT=b.MaBT LEFT JOIN deleted d ON d.MaBT=i.MaBT;
  UPDATE t SET TinhTrang=CASE WHEN i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'') THEN N''Đang bảo trì'' ELSE N''Đang hoạt động'' END
   FROM dbo.THIET_BI t JOIN inserted i ON i.MaTB=t.MaTB LEFT JOIN deleted d ON d.MaBT=i.MaBT
   WHERE(i.TrangThai IN(N''Đã xác nhận'',N''Đang thực hiện'') AND(d.MaBT IS NULL OR d.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận''))) OR(d.TrangThai=N''Đang thực hiện'' AND i.TrangThai=N''Đã hoàn thành'');
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_TB_Serial_BaoVe ON dbo.THIET_BI
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE(i.SoSerial<>d.SoSerial OR i.MaHH<>d.MaHH) AND EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB))
   THROW 52606,N''Thiết bị đã có lịch sử bảo trì; không đổi serial hoặc nguồn hàng hóa.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaTB=i.MaTB WHERE d.TinhTrang=N''Ngưng sử dụng'' AND i.TinhTrang<>d.TinhTrang)
   THROW 52606,N''Thiết bị đã ngưng sử dụng không được tự khôi phục.'',1;
  IF EXISTS(SELECT 1 FROM inserted i WHERE i.TinhTrang=N''Đang bảo trì'' AND NOT EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND b.TrangThai=N''Đang thực hiện''))
   THROW 52606,N''Tình trạng Đang bảo trì chỉ được đặt khi thực hiện phiếu bảo trì.'',1;
  IF EXISTS(SELECT 1 FROM inserted i WHERE EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(HOLDLOCK) WHERE b.MaTB=i.MaTB AND(
   (b.TrangThai=N''Đang thực hiện'' AND i.TinhTrang<>N''Đang bảo trì'') OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'') AND i.TinhTrang<>N''Hư hại'')
   OR(b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện'') AND i.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')))))
   THROW 52606,N''Thiết bị đang có phiếu mở; cập nhật tình trạng qua Lịch sử bảo trì.'',1;
 END;';
 -- Mỗi tài sản chỉ thanh lý một lần; giữ hồ sơ ngay trên thiết bị, không xóa tài sản.
 IF COL_LENGTH(N'dbo.THIET_BI',N'NgayThanhLy') IS NULL
  ALTER TABLE dbo.THIET_BI ADD NgayThanhLy datetime2(0) NULL,MaNVThanhLy nvarchar(50) NULL,
   LyDoThanhLy nvarchar(1000) NULL,GiaTriThanhLy decimal(18,2) NULL,
   TenThietBiThanhLy nvarchar(255) NULL,TenPhongThanhLy nvarchar(255) NULL,TenNhanVienThanhLy nvarchar(255) NULL;
 -- Giữ toàn bộ tên hợp lệ từ các danh mục nguồn (nvarchar(255)).
 IF EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.THIET_BI') AND name=N'TenThietBiThanhLy' AND max_length<510)
  ALTER TABLE dbo.THIET_BI ALTER COLUMN TenThietBiThanhLy nvarchar(255) NULL;
 IF EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.THIET_BI') AND name=N'TenPhongThanhLy' AND max_length<510)
  ALTER TABLE dbo.THIET_BI ALTER COLUMN TenPhongThanhLy nvarchar(255) NULL;
 IF EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.THIET_BI') AND name=N'TenNhanVienThanhLy' AND max_length<510)
  ALTER TABLE dbo.THIET_BI ALTER COLUMN TenNhanVienThanhLy nvarchar(255) NULL;
 IF OBJECT_ID(N'dbo.FK_TB_NhanVienThanhLy',N'F') IS NULL
  ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT FK_TB_NhanVienThanhLy FOREIGN KEY(MaNVThanhLy) REFERENCES dbo.NHAN_VIEN(MaNV);
 IF OBJECT_ID(N'dbo.CK_TB_ThanhLy',N'C') IS NULL
  EXEC sys.sp_executesql N'ALTER TABLE dbo.THIET_BI WITH CHECK ADD CONSTRAINT CK_TB_ThanhLy CHECK(
   (NgayThanhLy IS NULL AND MaNVThanhLy IS NULL AND LyDoThanhLy IS NULL AND GiaTriThanhLy IS NULL AND TenThietBiThanhLy IS NULL AND TenPhongThanhLy IS NULL AND TenNhanVienThanhLy IS NULL)
   OR (NgayThanhLy IS NOT NULL AND MaNVThanhLy IS NOT NULL AND LyDoThanhLy IS NOT NULL AND LEN(LTRIM(RTRIM(LyDoThanhLy)))>0
    AND GiaTriThanhLy IS NOT NULL AND GiaTriThanhLy>=0 AND TenThietBiThanhLy IS NOT NULL AND TenPhongThanhLy IS NOT NULL AND TenNhanVienThanhLy IS NOT NULL
    AND TinhTrang=N''Ngưng sử dụng'' AND TrangThai=N''Ngưng sử dụng'' AND MaPhong IS NULL));';
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_TB_ThanhLy_BaoVe ON dbo.THIET_BI
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM deleted WHERE NgayThanhLy IS NOT NULL)
   THROW 52610,N''Thiết bị đã thanh lý: giữ nguyên hồ sơ, không sửa, xóa hoặc khôi phục.'',1;
  IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.MaTB=i.MaTB WHERE i.NgayThanhLy IS NOT NULL AND
   (d.MaTB IS NULL OR d.TinhTrang<>N''Hư hại'' OR d.TrangThai IN(N''Ngưng sử dụng'',N''Ngừng sử dụng'')
    OR EXISTS(SELECT 1 FROM dbo.BAO_TRI_THIET_BI b WITH(UPDLOCK,HOLDLOCK) WHERE b.MaTB=i.MaTB AND b.TrangThai IN(N''Chưa xác nhận'',N''Đã xác nhận'',N''Đang thực hiện''))))
   THROW 52610,N''Chỉ thanh lý thiết bị hư hại chưa ngưng sử dụng và không có phiếu bảo trì mở.'',1;
 END;';
 -- Phiếu đã xác nhận từ phiên bản trước bắt đầu ngay khi đồng bộ; giữ giờ xác nhận cũ.
 -- Nếu có lịch tương lai, dừng để đối chiếu thay vì sửa ngày dự kiến đã khóa.
 EXEC sys.sp_executesql N'UPDATE dbo.BAO_TRI_THIET_BI SET TrangThai=N''Đang thực hiện'' WHERE TrangThai=N''Đã xác nhận'';';
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.AssetDisposal.Version')
  EXEC sys.sp_updateextendedproperty @name=N'RHM.AssetDisposal.Version',@value=1;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.AssetDisposal.Version',@value=1;
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraBaoTriSerial AS
 BEGIN
  SET NOCOUNT ON;
  IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''RHM.MaintenanceSerial.Version'' AND TRY_CONVERT(int,value)=1)
   THROW 52600,N''Chưa đồng bộ bảo trì serial; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
  IF COL_LENGTH(N''dbo.THIET_BI'',N''NgayThanhLy'') IS NULL
   OR OBJECT_ID(N''dbo.TR_TB_ThanhLy_BaoVe'',N''TR'') IS NULL
   OR OBJECT_ID(N''dbo.FK_TB_NhanVienThanhLy'',N''F'') IS NULL
   OR OBJECT_ID(N''dbo.CK_TB_ThanhLy'',N''C'') IS NULL
   OR EXISTS(SELECT 1 FROM sys.triggers WHERE name=N''TR_TB_ThanhLy_BaoVe'' AND is_disabled=1)
   THROW 52600,N''Chưa đồng bộ thanh lý; chạy toàn bộ QLBenhVienRangHamMat.sql.'',1;
  IF EXISTS(SELECT 1 FROM (VALUES(N''NgayXacNhan''),(N''NgayThucHien'')) e(N) LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND c.name=e.N
   WHERE c.column_id IS NULL OR TYPE_NAME(c.user_type_id)<>N''datetime2'' OR c.scale<>0 OR c.is_nullable<>1)
   THROW 52600,N''Thiếu hoặc sai kiểu thời điểm xác nhận/thực hiện bảo trì.'',1;
  IF EXISTS(SELECT 1 FROM (VALUES(N''UQ_THIET_BI_SoSerial'',N''UQ''),(N''CK_TB_Serial_KhongTrong'',N''C''),(N''CK_TB_TinhTrang_BaoTri'',N''C''),(N''CK_BT_VongDoi'',N''C''),(N''CK_BT_NoiDung'',N''C''),
   (N''FK_BAO_TRI_THIET_BI_MaTB'',N''F''),(N''FK_BAO_TRI_THIET_BI_MaNV'',N''F''),(N''TR_BT_Serial_VongDoi'',N''TR''),(N''TR_TB_Serial_BaoVe'',N''TR'')) e(N,T) WHERE OBJECT_ID(N''dbo.''+e.N,e.T) IS NULL)
   THROW 52600,N''Thiếu liên kết hoặc bảo vệ bảo trì theo serial.'',1;
  IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND name=N''UX_BT_Serial_PhieuMo'' AND is_unique=1 AND has_filter=1 AND is_disabled=0
   AND filter_definition LIKE N''%Chưa xác nhận%'' AND filter_definition LIKE N''%Đã xác nhận%'' AND filter_definition LIKE N''%Đang thực hiện%'')
   OR NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.THIET_BI'') AND name=N''UQ_THIET_BI_SoSerial'' AND is_unique=1 AND is_disabled=0)
   OR EXISTS(SELECT 1 FROM sys.triggers WHERE name IN(N''TR_BT_Serial_VongDoi'',N''TR_TB_Serial_BaoVe'') AND is_disabled=1)
   OR EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id IN(OBJECT_ID(N''dbo.BAO_TRI_THIET_BI''),OBJECT_ID(N''dbo.THIET_BI'')) AND(is_disabled=1 OR is_not_trusted=1))
   OR EXISTS(SELECT 1 FROM sys.foreign_keys WHERE parent_object_id=OBJECT_ID(N''dbo.BAO_TRI_THIET_BI'') AND(is_disabled=1 OR is_not_trusted=1))
   THROW 52600,N''Index/ràng buộc/trigger bảo trì bị tắt hoặc chưa trusted.'',1;
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraSchema AS
 BEGIN
  SET NOCOUNT ON;
  EXEC dbo.usp_RHM_KiemTraSchemaNen;
  EXEC dbo.usp_RHM_KiemTraKeThuoc;
  EXEC dbo.usp_RHM_KiemTraDongBoV9;
  EXEC dbo.usp_RHM_KiemTraBaoTriSerial;
 END;';
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.MaintenanceSerial.Version')
  EXEC sys.sp_updateextendedproperty @name=N'RHM.MaintenanceSerial.Version',@value=1;
 ELSE EXEC sys.sp_addextendedproperty @name=N'RHM.MaintenanceSerial.Version',@value=1;
 EXEC dbo.usp_RHM_KiemTraBaoTriSerial;
 COMMIT TRANSACTION;
 EXEC sys.sp_set_session_context @key=N'RHM.MaintenanceSerial.Completed',@value=1;
 PRINT N'HOÀN TẤT BẢO TRÌ SERIAL: liên kết thiết bị, vòng đời phiếu và tình trạng vật lý đã đồng bộ.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO

-- ============================================================================
-- PHA 7: PHAN QUYEN THEO VAI TRO
-- Gop noi dung tu 01_TaoBangPhanQuyen.sql; cac pha SQL truoc do giu nguyen.
-- Guard: chi tao quyen khi pha bao tri serial da dong bo thanh cong.
-- ============================================================================
-- Chạy trên database QLBenhVienRangHamMat đang được ứng dụng kết nối.
-- Không xóa hoặc sửa tài khoản/vai trò đang có. Chạy lại an toàn.
SET XACT_ABORT ON;
EXEC sys.sp_set_session_context @key=N'RHM.RolePermissions.Completed',@value=0;
BEGIN TRY
    BEGIN TRANSACTION;

    IF DB_NAME() <> N'QLBenhVienRangHamMat'
        THROW 52700, N'Khong dung database QLBenhVienRangHamMat; dung cap nhat phan quyen.', 1;
    IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.MaintenanceSerial.Completed')),0)<>1 OR NOT EXISTS (
        SELECT 1 FROM sys.extended_properties
        WHERE class = 0 AND name = N'RHM.MaintenanceSerial.Version'
          AND TRY_CONVERT(int, value) = 1
    )
        THROW 52701, N'Pha 6 chua hoan tat; khong cai phan quyen.', 1;
    IF OBJECT_ID(N'dbo.VAI_TRO', N'U') IS NULL
        THROW 52702, N'Thieu bang VAI_TRO; khong the khoi tao phan quyen.', 1;

    IF OBJECT_ID(N'dbo.PHAN_QUYEN_VAI_TRO', N'U') IS NULL
    BEGIN
        CREATE TABLE [dbo].[PHAN_QUYEN_VAI_TRO]
        (
            MaVaiTro NVARCHAR(50) NOT NULL,
            MaPhanHe NVARCHAR(60) NOT NULL,
            DuocTruyCap BIT NOT NULL CONSTRAINT DF_PHAN_QUYEN_VAI_TRO_TruyCap DEFAULT (0),
            NgayCapNhat DATETIME2(0) NOT NULL CONSTRAINT DF_PHAN_QUYEN_VAI_TRO_NgayCapNhat DEFAULT (SYSDATETIME()),
            CONSTRAINT PK_PHAN_QUYEN_VAI_TRO PRIMARY KEY (MaVaiTro, MaPhanHe)
        );
    END;

    -- Chỉ khởi tạo các vai trò chưa từng được cấu hình. Không ghi đè quyền đã lưu.
    -- Admin và Quản trị nhận toàn bộ quyền (riêng Tài khoản được bảo vệ khi sửa).
    -- User giữ 3 quyền cơ bản như MainWindow bản trước; các vai trò khác mặc định 0.
    INSERT INTO dbo.PHAN_QUYEN_VAI_TRO (MaVaiTro, MaPhanHe, DuocTruyCap)
    SELECT vt.MaVaiTro, mh.MaPhanHe,
        CAST(CASE
            WHEN vt.TenVaiTro IN (N'Admin', N'Quản trị', N'Quản trị viên') THEN 1
            WHEN vt.TenVaiTro = N'User' AND mh.MaPhanHe IN
                 (N'TongQuan', N'CaLamViec', N'XinNghiViec') THEN 1
            ELSE 0
        END AS BIT)
    FROM dbo.VAI_TRO AS vt
    CROSS JOIN (VALUES
        (N'TongQuan'), (N'BenhNhan'), (N'KhamDieuTri'),
        (N'DichVuThucHien'), (N'DonThuoc'), (N'NhanSu'),
        (N'ChungChiNhanVien'), (N'CaLamViec'), (N'ThietBi'),
        (N'BaoTri'), (N'Kho'), (N'DanhMucHangHoa'),
        (N'NhaCungCap'), (N'NhapXuatVatTu'), (N'LichKham'),
        (N'DichVu'), (N'HoaDon'), (N'BangLuong'), (N'ChamCong'),
        (N'ChinhSachLuong'), (N'TaiKhoan'), (N'BaoCao'),
        (N'PhieuHuongDan'), (N'NhatKy'), (N'XinNghiViec')
    ) AS mh(MaPhanHe)
    WHERE NOT EXISTS
    (
        SELECT 1 FROM dbo.PHAN_QUYEN_VAI_TRO AS pq
        WHERE pq.MaVaiTro = vt.MaVaiTro
    );

    COMMIT TRANSACTION;
    EXEC sys.sp_set_session_context @key=N'RHM.RolePermissions.Completed',@value=1;
    PRINT N'Đã tạo/kiểm tra PHAN_QUYEN_VAI_TRO và khởi tạo quyền mặc định.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

SELECT vt.MaVaiTro, vt.TenVaiTro,
       SUM(CASE WHEN pq.DuocTruyCap = 1 THEN 1 ELSE 0 END) AS SoPhanHeDuocMo
FROM dbo.VAI_TRO AS vt
LEFT JOIN dbo.PHAN_QUYEN_VAI_TRO AS pq ON pq.MaVaiTro = vt.MaVaiTro
GROUP BY vt.MaVaiTro, vt.TenVaiTro
ORDER BY vt.MaVaiTro;
GO

-- BEGIN SPRINT 3 THANH TAN: cài mới/nâng cấp trong file SQL duy nhất.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
EXEC sys.sp_set_session_context @key=N'RHM.AuditSchema.Completed',@value=0;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.RolePermissions.Completed')),0)<>1
 THROW 53000,N'Pha phân quyền chưa hoàn tất; không nâng cấp nhật ký.',1;
IF CONVERT(int,SERVERPROPERTY('ProductMajorVersion')) < 13
 THROW 53000,N'Cần SQL Server 2016 SP1 trở lên.',1;
IF OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC',N'U') IS NULL
 THROW 53001,N'Cần cài schema bệnh viện trước migration Sprint 3.',1;
BEGIN TRY
 BEGIN TRAN;
 IF OBJECT_ID(N'dbo.PHIEN_DANG_NHAP',N'U') IS NULL
 EXEC(N'CREATE TABLE [dbo].[PHIEN_DANG_NHAP](
 MaPhien uniqueidentifier NOT NULL CONSTRAINT PK_S3_Phien PRIMARY KEY,
 MaTK nvarchar(50) NOT NULL CONSTRAINT FK_S3_Phien_TK REFERENCES dbo.TAI_KHOAN(MaTK),
 DangNhapUtc datetime2(0) NOT NULL, DangXuatUtc datetime2(0) NULL,
 HoatDongCuoiUtc datetime2(0) NOT NULL,
 TrangThaiPhien nvarchar(50) NOT NULL,
 LyDoKetThuc nvarchar(255) NULL,
 CONSTRAINT CK_S3_Phien CHECK(TrangThaiPhien IN(N''Đang mở'',N''Đã đăng xuất'',N''Kết thúc bất thường'')))');
 IF COL_LENGTH(N'dbo.NHAT_KY_THAO_TAC',N'MaPhien') IS NULL
  ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD MaPhien uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.NHAT_KY_THAO_TAC',N'ThoiGianUtc') IS NULL
  ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD ThoiGianUtc datetime2(0) NULL;
 IF COL_LENGTH(N'dbo.NHAT_KY_THAO_TAC',N'MaSuKien') IS NULL
  ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD MaSuKien uniqueidentifier NULL;
 IF COL_LENGTH(N'dbo.NHAT_KY_THAO_TAC',N'PhanHe') IS NULL
  ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD PhanHe nvarchar(100) NULL;
 -- Dọn nhật ký cũ chưa xác định múi giờ; không suy đoán UTC từ ThoiGian.
 -- SQL động để cài mới vẫn biên dịch được khi cột UTC vừa được thêm trong batch này.
 -- Chạy lại chỉ xét bản ghi thiếu UTC, giữ nguyên nhật ký hiện tại và phiên đăng nhập.
 EXEC(N'DELETE FROM dbo.NHAT_KY_THAO_TAC WHERE ThoiGianUtc IS NULL;');
 -- Các DAL cũ không chỉ định cột mới vẫn nhận UTC/event/phiên từ kết nối đã xác thực.
 -- Không WITH VALUES: không gán thời gian hiện tại cho dữ liệu lịch sử chưa rõ múi giờ.
 IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND parent_column_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC'),N'ThoiGianUtc','ColumnId'))
  EXEC(N'ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD CONSTRAINT DF_S3_AuditUtc DEFAULT(SYSUTCDATETIME()) FOR ThoiGianUtc');
 IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND parent_column_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC'),N'MaSuKien','ColumnId'))
  EXEC(N'ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD CONSTRAINT DF_S3_AuditEvent DEFAULT(NEWID()) FOR MaSuKien');
 IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND parent_column_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC'),N'MaPhien','ColumnId'))
  EXEC(N'ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD CONSTRAINT DF_S3_AuditSession DEFAULT(TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N''RHM.MaPhien''))) FOR MaPhien');
 IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_S3_NhatKy_Phien')
  EXEC(N'ALTER TABLE dbo.NHAT_KY_THAO_TAC ADD CONSTRAINT FK_S3_NhatKy_Phien FOREIGN KEY(MaPhien) REFERENCES dbo.PHIEN_DANG_NHAP(MaPhien)');
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND name=N'UX_S3_Event')
  EXEC(N'CREATE UNIQUE INDEX UX_S3_Event ON dbo.NHAT_KY_THAO_TAC(MaSuKien) WHERE MaSuKien IS NOT NULL');
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND name=N'IX_S3_Log_Time')
  EXEC(N'CREATE INDEX IX_S3_Log_Time ON dbo.NHAT_KY_THAO_TAC(ThoiGianUtc DESC,MaNK DESC) INCLUDE(MaTK,MaPhien,HanhDong,PhanHe)');
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.NHAT_KY_THAO_TAC') AND name=N'IX_S3_Log_Account')
  EXEC(N'CREATE INDEX IX_S3_Log_Account ON dbo.NHAT_KY_THAO_TAC(MaTK,ThoiGianUtc DESC)');
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.PHIEN_DANG_NHAP') AND name=N'IX_S3_Phien_Heartbeat')
  EXEC(N'CREATE INDEX IX_S3_Phien_Heartbeat ON dbo.PHIEN_DANG_NHAP(TrangThaiPhien,HoatDongCuoiUtc) INCLUDE(MaTK)');
 IF COL_LENGTH(N'dbo.CHUC_VU',N'TrangThai') IS NULL
  ALTER TABLE dbo.CHUC_VU ADD TrangThai nvarchar(50) NOT NULL CONSTRAINT DF_S3_ChucVu DEFAULT(N'Đang hoạt động') WITH VALUES;
 IF COL_LENGTH(N'dbo.NGAY_NGHI_LE',N'TrangThai') IS NULL
  ALTER TABLE dbo.NGAY_NGHI_LE ADD TrangThai nvarchar(50) NOT NULL CONSTRAINT DF_S3_NgayNghi DEFAULT(N'Đang hoạt động') WITH VALUES;
 IF COL_LENGTH(N'dbo.DICH_VU_TINH_TRANG',N'TrangThai') IS NULL
  ALTER TABLE dbo.DICH_VU_TINH_TRANG ADD TrangThai nvarchar(50) NOT NULL CONSTRAINT DF_S3_DVTT DEFAULT(N'Đang hoạt động') WITH VALUES;
 COMMIT;
 EXEC sys.sp_set_session_context @key=N'RHM.AuditSchema.Completed',@value=1;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;

GO
-- Audit các phân hệ không đi qua editor chung. Chỉ ghi khi kết nối mang phiên đã xác thực;
-- script cài đặt/fixture SQL ngoài ứng dụng không bị gán người thao tác giả.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
EXEC sys.sp_set_session_context @key=N'RHM.AuditTriggers.Completed',@value=0;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.AuditSchema.Completed')),0)<>1
 THROW 53020,N'Pha schema nhật ký chưa hoàn tất; không cập nhật trigger audit.',1;
BEGIN TRY
 BEGIN TRAN;
 DECLARE @s3Table sysname,@s3Join nvarchar(max),@s3Id nvarchar(max),@s3Before nvarchar(max),@s3After nvarchar(max),@s3Sql nvarchar(max),@s3Action nvarchar(max),@s3Gate nvarchar(max);
 DECLARE s3Tables CURSOR LOCAL FAST_FORWARD FOR
 SELECT t.name FROM sys.tables t WHERE t.name IN
 (N'NHAN_VIEN',N'TAI_KHOAN',N'VAI_TRO',N'PHAN_QUYEN_VAI_TRO',N'KHO',N'HANG_HOA',N'THUOC',N'VAT_TU',N'THIET_BI',N'LO_HANG_HOA',
  N'PHIEU_NHAP',N'PHIEU_XUAT',N'CHI_TIET_PHIEU_NHAP',N'CHI_TIET_PHIEU_XUAT',N'HOA_DON_NHAP',N'THANH_TOAN',
  N'BANG_LUONG',N'CHI_TIET_LUONG',N'CHI_TIET_HOA_HONG_LUONG',N'CHINH_SACH_LUONG',N'CHAM_CONG',N'LAM_THEM_GIO',
  N'CHUNG_CHI_NHAN_VIEN',N'DON_XIN_NGHI',N'LICH_LAM_VIEC',N'CA_LAM',N'CA_THEO_NGAY',N'PHAN_CONG_THAY_THE',N'XAC_NHAN_DOI_LICH_KHAM',N'PHU_TA_DICH_VU');
 OPEN s3Tables; FETCH NEXT FROM s3Tables INTO @s3Table;
 WHILE @@FETCH_STATUS=0
 BEGIN
  SET @s3Join=NULL;SET @s3Id=NULL;SET @s3Before=NULL;SET @s3After=NULL;
  SELECT @s3Join=COALESCE(@s3Join+N' AND ',N'')+N'i.'+QUOTENAME(c.name)+N'=d.'+QUOTENAME(c.name),
    @s3Id=COALESCE(@s3Id+N'+N''/''+',N'')+N'COALESCE(CONVERT(nvarchar(100),i.'+QUOTENAME(c.name)+N'),CONVERT(nvarchar(100),d.'+QUOTENAME(c.name)+N'))',
    @s3Before=COALESCE(@s3Before+N',',N'')+N'd.'+QUOTENAME(c.name),
    @s3After=COALESCE(@s3After+N',',N'')+N'i.'+QUOTENAME(c.name)
   FROM sys.indexes ix JOIN sys.index_columns ic ON ic.object_id=ix.object_id AND ic.index_id=ix.index_id
   JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
   WHERE ix.object_id=OBJECT_ID(N'dbo.'+@s3Table) AND ix.is_primary_key=1 ORDER BY ic.key_ordinal;
  IF @s3Join IS NULL THROW 53021,N'Bảng audit thiếu khóa chính.',1;
  IF COL_LENGTH(N'dbo.'+@s3Table,N'TrangThai') IS NOT NULL
  BEGIN SET @s3Before+=N',d.TrangThai';SET @s3After+=N',i.TrangThai';END;
  SET @s3Action=N'N''UPDATE''';
  IF COL_LENGTH(N'dbo.'+@s3Table,N'TrangThai') IS NOT NULL
   SET @s3Action=N'CASE WHEN i.TrangThai=d.TrangThai THEN N''UPDATE'' WHEN i.TrangThai=N''Đã duyệt'' THEN N''APPROVE'' WHEN i.TrangThai=N''Đã xác nhận'' THEN N''CONFIRM'' WHEN i.TrangThai IN(N''Đã chốt'',N''Đã hoàn thành'') THEN N''FINALIZE'' WHEN i.TrangThai IN(N''Hủy'',N''Đã hủy'') THEN N''CANCEL'' WHEN i.TrangThai IN(N''Khóa'',N''Đã khóa'') THEN N''LOCK'' ELSE N''UPDATE'' END';
  IF @s3Table=N'TAI_KHOAN'
   SET @s3Action=N'CASE WHEN i.MaVaiTro<>d.MaVaiTro THEN N''ROLE_CHANGE'' WHEN i.TrangThai<>d.TrangThai AND i.TrangThai<>N''Đang hoạt động'' THEN N''ACCOUNT_LOCK'' WHEN i.TrangThai<>d.TrangThai AND i.TrangThai=N''Đang hoạt động'' THEN N''ACCOUNT_RESTORE'' ELSE N''UPDATE'' END';
  IF @s3Table=N'VAI_TRO' SET @s3Action=N'N''ROLE_CHANGE''';
  IF @s3Table=N'PHAN_QUYEN_VAI_TRO' SET @s3Action=N'N''PERMISSION_CHANGE''';
  SET @s3Before+=N',@changed AS TruongDaDoi';SET @s3After+=N',@changed AS TruongDaDoi';
  SET @s3Gate=N'';
  IF @s3Table IN(N'TAI_KHOAN',N'VAI_TRO',N'PHAN_QUYEN_VAI_TRO')
   SET @s3Gate=N'IF NOT EXISTS(SELECT 1 FROM dbo.TAI_KHOAN t JOIN dbo.VAI_TRO v ON v.MaVaiTro=t.MaVaiTro WHERE t.MaTK=@actor AND UPPER(LTRIM(RTRIM(v.TenVaiTro))) IN(N''ADMIN'',N''QUẢN TRỊ'')) THROW 53023,N''Chỉ quản trị viên được sửa tài khoản, vai trò và phân quyền.'',1;';
  SET @s3Sql=N'CREATE OR ALTER TRIGGER dbo.'+QUOTENAME(N'TR_S3_Audit_'+@s3Table)+N' ON dbo.'+QUOTENAME(@s3Table)+N' AFTER INSERT,UPDATE,DELETE AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @session uniqueidentifier=TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N''RHM.MaPhien''));
 IF @session IS NULL RETURN;
 DECLARE @actor nvarchar(50);
 SELECT @actor=s.MaTK FROM dbo.PHIEN_DANG_NHAP s WITH(HOLDLOCK)
 JOIN dbo.TAI_KHOAN t WITH(HOLDLOCK) ON t.MaTK=s.MaTK
 JOIN dbo.NHAN_VIEN n WITH(HOLDLOCK) ON n.MaNV=t.MaNV
 WHERE s.MaPhien=@session AND s.TrangThaiPhien=N''Đang mở''
 AND s.HoatDongCuoiUtc>=DATEADD(minute,-5,SYSUTCDATETIME())
 AND t.TrangThai=N''Đang hoạt động'' AND n.TrangThai=N''Đang làm việc'';
 IF @actor IS NULL THROW 53022,N''Không có phiên hợp lệ để ghi audit nghiệp vụ.'',1;
 '+@s3Gate+N'
 DECLARE @mask varbinary(max)=COLUMNS_UPDATED();
 DECLARE @changed nvarchar(max)=STUFF((SELECT N'',''+c.name FROM sys.columns c
 WHERE c.object_id=OBJECT_ID(N''dbo.'+@s3Table+N''')
 AND c.name NOT LIKE N''%MatKhau%'' AND c.name NOT LIKE N''%Token%'' AND c.name NOT LIKE N''%Secret%'' AND c.name NOT LIKE N''%ApiKey%''
 AND CONVERT(int,SUBSTRING(@mask,(c.column_id-1)/8+1,1)) & CONVERT(int,POWER(2,(c.column_id-1)%8))>0
 ORDER BY c.column_id FOR XML PATH(''''),TYPE).value(''.'',''nvarchar(max)''),1,1,N'''');
 INSERT dbo.NHAT_KY_THAO_TAC(MaNK,MaTK,ThoiGian,ThoiGianUtc,MaPhien,MaSuKien,PhanHe,HanhDong,LoaiDoiTuong,MaDoiTuong,KetQua,DuLieuTruoc,DuLieuSau)
 SELECT N''NK''+CONVERT(nvarchar(36),NEWID()),@actor,SYSDATETIME(),SYSUTCDATETIME(),@session,NEWID(),N'''+@s3Table+N''',
 CASE WHEN NOT EXISTS(SELECT 1 FROM deleted) THEN N''CREATE'' WHEN NOT EXISTS(SELECT 1 FROM inserted) THEN N''CANCEL'' ELSE '+@s3Action+N' END,
 N'''+@s3Table+N''',CASE WHEN LEN('+@s3Id+N')>50 THEN LEFT(CONVERT(varchar(64),HASHBYTES(''SHA2_256'','+@s3Id+N'),2),50) ELSE '+@s3Id+N' END,N''Thành công'',
 (SELECT '+@s3Before+N' FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES),
 (SELECT '+@s3After+N' FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)
 FROM inserted i FULL JOIN deleted d ON '+@s3Join+N';
END;';
  EXEC sys.sp_executesql @s3Sql;
  FETCH NEXT FROM s3Tables INTO @s3Table;
 END;
 CLOSE s3Tables;DEALLOCATE s3Tables;
 COMMIT;
 EXEC sys.sp_set_session_context @key=N'RHM.AuditTriggers.Completed',@value=1;
 PRINT N'Sprint 3: danh mục, nhật ký và phiên đăng nhập đã sẵn sàng.';
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
-- END SPRINT 3 THANH TAN
-- Danh mục ngày nghỉ ngừng dùng không tham gia tính công/lương mới.
-- Giữ nguyên chứng từ đã chốt; chỉ cập nhật định nghĩa module đọc danh mục.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
EXEC sys.sp_set_session_context @key=N'RHM.PayrollCatalog.Completed',@value=0;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.AuditTriggers.Completed')),0)<>1
 THROW 53020,N'Pha audit chưa hoàn tất; không cập nhật module công/lương.',1;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @s3Module nvarchar(max),@s3OldModule nvarchar(max),@s3Create int;
DECLARE s3Payroll CURSOR LOCAL FAST_FORWARD FOR
 SELECT m.definition FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id
 WHERE o.type IN('V','P','TR','FN','IF','TF') AND m.definition LIKE N'%dbo.NGAY_NGHI_LE%'
 AND (m.definition LIKE N'%h.CoHuongLuong=1%' OR m.definition LIKE N'%x.CoHuongLuong=1%')
 AND m.definition NOT LIKE N'%h.TrangThai=N''Đang hoạt động''%' AND m.definition NOT LIKE N'%x.TrangThai=N''Đang hoạt động''%';
OPEN s3Payroll; FETCH NEXT FROM s3Payroll INTO @s3Module;
WHILE @@FETCH_STATUS=0
BEGIN
 SET @s3OldModule=@s3Module;
 SET @s3Module=REPLACE(REPLACE(@s3Module,N'h.CoHuongLuong=1',N'h.CoHuongLuong=1 AND h.TrangThai=N''Đang hoạt động'''),N'x.CoHuongLuong=1',N'x.CoHuongLuong=1 AND x.TrangThai=N''Đang hoạt động''');
 SET @s3Module=REPLACE(@s3Module,N'CREATE OR ALTER ',N'ALTER ');
 SET @s3Create=CHARINDEX(N'CREATE',UPPER(@s3Module));
 IF @s3Create>0 AND @s3Create<20 SET @s3Module=STUFF(@s3Module,@s3Create,6,N'ALTER');
 IF @s3Module<>@s3OldModule EXEC sys.sp_executesql @s3Module;
 FETCH NEXT FROM s3Payroll INTO @s3Module;
END;
CLOSE s3Payroll;DEALLOCATE s3Payroll;
COMMIT TRANSACTION;
EXEC sys.sp_set_session_context @key=N'RHM.PayrollCatalog.Completed',@value=1;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 IF CURSOR_STATUS('local','s3Payroll')>=0 CLOSE s3Payroll;
 IF CURSOR_STATUS('local','s3Payroll')>-3 DEALLOCATE s3Payroll;
 THROW;
END CATCH;
GO

-- BEGIN SPRINT 3 FOUNDATION 20261107: loại khám/phụ thu dùng bởi ET/DAL/BUS/WPF hiện tại.
-- Đặt sau mọi định nghĩa cũ; không hồi tố loại khám/phụ thu, không sửa tiền đã chốt.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
EXEC sys.sp_set_session_context @key=N'RHM.Sprint3Foundation.Completed',@value=0;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.HospitalWorkflow.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.PrescriptionFlow.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.SqlV9.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.PayrollCatalog.Completed')),0)<>1
 OR OBJECT_ID(N'dbo.TR_HD_ChotHoanTat',N'TR') IS NULL
 THROW 53400,N'Cần chạy thành công các pha SQL trước nền tảng Sprint 3.',1;
BEGIN TRY
 BEGIN TRANSACTION;
 DECLARE @s3FoundationLock int;
 EXEC @s3FoundationLock=sys.sp_getapplock @Resource=N'RHM:Sprint3Foundation:Migration',
  @LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=15000;
 IF @s3FoundationLock<0 THROW 53400,N'Không lấy được khóa nâng cấp nền tảng Sprint 3.',1;

 IF COL_LENGTH(N'dbo.PHIEU_KHAM_BENH',N'LoaiKham') IS NULL
  EXEC(N'ALTER TABLE dbo.PHIEU_KHAM_BENH ADD LoaiKham nvarchar(20) NOT NULL CONSTRAINT DF_PKB_LoaiKham DEFAULT(N''Thông thường'') WITH VALUES;');
 IF COL_LENGTH(N'dbo.PHIEU_KHAM_BENH',N'PhiPhuThuDichVu') IS NULL
  EXEC(N'ALTER TABLE dbo.PHIEU_KHAM_BENH ADD PhiPhuThuDichVu decimal(18,2) NOT NULL CONSTRAINT DF_PKB_PhiPhuThuDichVu DEFAULT(0) WITH VALUES;');
 IF COL_LENGTH(N'dbo.CHI_TIET_HOA_DON',N'MaPhieuPhuThu') IS NULL
  EXEC(N'ALTER TABLE dbo.CHI_TIET_HOA_DON ADD MaPhieuPhuThu nvarchar(50) NULL;');
 IF OBJECT_ID(N'dbo.CK_PKB_LoaiKham_PhuThu',N'C') IS NULL
  EXEC(N'ALTER TABLE dbo.PHIEU_KHAM_BENH WITH CHECK ADD CONSTRAINT CK_PKB_LoaiKham_PhuThu CHECK
   ((LoaiKham=N''Thông thường'' AND PhiPhuThuDichVu=0)
    OR(LoaiKham=N''Dịch vụ'' AND PhiPhuThuDichVu=30000 AND MaLich IS NULL));');
 IF OBJECT_ID(N'dbo.FK_CTHD_PhieuPhuThu',N'F') IS NULL
  EXEC(N'ALTER TABLE dbo.CHI_TIET_HOA_DON WITH CHECK ADD CONSTRAINT FK_CTHD_PhieuPhuThu
   FOREIGN KEY(MaPhieuPhuThu) REFERENCES dbo.PHIEU_KHAM_BENH(MaPhieu);');
 IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.CHI_TIET_HOA_DON') AND name=N'UX_CTHD_PhieuPhuThu')
  EXEC(N'CREATE UNIQUE INDEX UX_CTHD_PhieuPhuThu ON dbo.CHI_TIET_HOA_DON(MaPhieuPhuThu) WHERE MaPhieuPhuThu IS NOT NULL;');
 IF OBJECT_ID(N'dbo.CK_CHI_TIET_HOA_DON_3',N'C') IS NOT NULL
  ALTER TABLE dbo.CHI_TIET_HOA_DON DROP CONSTRAINT CK_CHI_TIET_HOA_DON_3;
 EXEC(N'ALTER TABLE dbo.CHI_TIET_HOA_DON WITH CHECK ADD CONSTRAINT CK_CHI_TIET_HOA_DON_3 CHECK
  ((MaDVThucHien IS NOT NULL AND MaCTPX IS NULL AND MaCTDT IS NULL AND MaPhieuPhuThu IS NULL AND DonGia IS NULL)
   OR(MaDVThucHien IS NULL AND MaCTPX IS NOT NULL AND MaCTDT IS NULL AND MaPhieuPhuThu IS NULL AND DonGia IS NOT NULL AND DonGia>=0)
   OR(MaDVThucHien IS NULL AND MaCTPX IS NULL AND MaCTDT IS NOT NULL AND MaPhieuPhuThu IS NULL AND DonGia IS NOT NULL AND DonGia>=0)
   OR(MaDVThucHien IS NULL AND MaCTPX IS NULL AND MaCTDT IS NULL AND MaPhieuPhuThu IS NOT NULL AND DonGia IS NOT NULL AND DonGia=30000));');

 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_PKB_KhoaLoaiKham ON dbo.PHIEU_KHAM_BENH AFTER UPDATE AS
 BEGIN
  SET NOCOUNT ON;
  IF UPDATE(MaPhieu) THROW 53401,N''Mã phiếu tiếp nhận là định danh bất biến.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPhieu=i.MaPhieu
   WHERE EXISTS(SELECT i.LoaiKham,i.PhiPhuThuDichVu EXCEPT SELECT d.LoaiKham,d.PhiPhuThuDichVu))
   THROW 53401,N''Loại khám và mức phụ thu đã lưu khi tiếp nhận được giữ nguyên.'',1;
 END;';

 -- Giữ toàn bộ kiểm nguồn/khóa chứng từ/đổi đơn sang xuất kho của HospitalWorkflow3.
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_CTHD_TinhTien ON dbo.CHI_TIET_HOA_DON
 AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF TRIGGER_NESTLEVEL(OBJECT_ID(N''dbo.TR_CTHD_TinhTien''))>1 RETURN;
  DECLARE @lock nvarchar(50);
  SELECT @lock=h.MaHD FROM dbo.HOA_DON h WITH(UPDLOCK,HOLDLOCK)
   WHERE h.MaHD IN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted);
  IF EXISTS(SELECT 1 FROM dbo.HOA_DON h JOIN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted) z ON z.MaHD=h.MaHD WHERE h.TrangThai<>N''Nháp'')
   THROW 51001,N''Chỉ thay đổi chi tiết hóa đơn nháp.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD
   LEFT JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=i.MaCTPX
   WHERE h.TaoKhiHoanTat=1 AND(i.MaCTPX IS NULL OR NOT EXISTS(
    SELECT 1 FROM dbo.CHI_TIET_HOA_DON pending WHERE pending.MaHD=i.MaHD AND pending.MaCTDT=x.MaCTDT
     AND pending.DonGia=i.DonGia AND pending.NoiDung=i.NoiDung)))
   THROW 52231,N''Hóa đơn đã chốt nguồn; chỉ thay thuốc theo đơn bằng đúng phần xuất kho.'',1;
  IF EXISTS(SELECT 1 FROM deleted d JOIN dbo.HOA_DON h ON h.MaHD=d.MaHD
   LEFT JOIN dbo.CHI_TIET_DON_THUOC rx ON rx.MaCTDT=d.MaCTDT
   OUTER APPLY(SELECT SUM(x.SoLuong) Qty,SUM(c.ThanhTien) Amount FROM dbo.CHI_TIET_HOA_DON c
    JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=c.MaCTPX WHERE c.MaHD=d.MaHD AND x.MaCTDT=d.MaCTDT) a
   WHERE h.TaoKhiHoanTat=1 AND(d.MaCTDT IS NULL OR EXISTS(SELECT 1 FROM inserted i WHERE i.MaCTHD=d.MaCTHD)
    OR COALESCE(a.Qty,0)<>rx.SoLuong OR COALESCE(a.Amount,0)<>d.ThanhTien))
   THROW 52232,N''Không xóa/sửa khoản đã chốt; phần xuất phải khớp toàn bộ lượng và tiền đơn thuốc.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD
   LEFT JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=i.MaDVThucHien
   LEFT JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=i.MaCTPX
   LEFT JOIN dbo.PHIEU_XUAT p ON p.MaPX=x.MaPX
   LEFT JOIN dbo.CHI_TIET_DON_THUOC d ON d.MaCTDT=COALESCE(i.MaCTDT,x.MaCTDT)
   LEFT JOIN dbo.DON_THUOC r ON r.MaDT=d.MaDT
   WHERE(i.MaDVThucHien IS NOT NULL AND(s.MaLS<>h.MaLS OR s.TrangThai<>N''Đã xác nhận''))
    OR(i.MaCTPX IS NOT NULL AND(x.MaCTDT IS NULL OR p.MaLS<>h.MaLS OR r.MaLS<>h.MaLS OR p.TrangThai<>N''Đã ghi sổ''))
    OR(i.MaCTDT IS NOT NULL AND(r.MaLS<>h.MaLS OR r.TrangThai<>N''Đã xác nhận'' OR r.NgayKe>h.NgayLap
     OR NULLIF(LTRIM(RTRIM(d.TenThuocChot)),N'''') IS NULL OR NULLIF(LTRIM(RTRIM(d.HamLuongChot)),N'''') IS NULL
     OR NULLIF(LTRIM(RTRIM(d.DonViTinhChot)),N'''') IS NULL)))
   THROW 51002,N''Nguồn thu phải cùng lượt: dịch vụ xác nhận, đơn đã ký hoặc thuốc đã xuất.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD
   JOIN dbo.PHIEU_KHAM_BENH p WITH(HOLDLOCK) ON p.MaPhieu=i.MaPhieuPhuThu
   WHERE p.LoaiKham<>N''Dịch vụ'' OR p.PhiPhuThuDichVu<>30000 OR NOT EXISTS(
    SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaLS=h.MaLS AND l.MaPhieu=p.MaPhieu))
   THROW 53402,N''Phụ thu phải lấy từ phiếu khám dịch vụ của đúng lần khám trên hóa đơn.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.HOA_DON h ON h.MaHD=i.MaHD
   JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=i.MaCTPX JOIN dbo.CHI_TIET_DON_THUOC rx ON rx.MaCTDT=x.MaCTDT
   WHERE h.TaoKhiHoanTat=1 AND(SELECT SUM(y.SoLuong) FROM dbo.CHI_TIET_HOA_DON c
    JOIN dbo.CHI_TIET_PHIEU_XUAT y ON y.MaCTPX=c.MaCTPX WHERE c.MaHD=i.MaHD AND y.MaCTDT=x.MaCTDT)>rx.SoLuong)
   THROW 52233,N''Phần xuất vượt lượng đã chốt.'',1;
  UPDATE c SET ThanhTien=CASE WHEN c.MaDVThucHien IS NOT NULL THEN s.ThanhTien
   WHEN c.MaPhieuPhuThu IS NOT NULL THEN p.PhiPhuThuDichVu
   ELSE CAST(ROUND(COALESCE(x.SoLuong,d.SoLuong)*c.DonGia,2) AS decimal(18,2)) END
  FROM dbo.CHI_TIET_HOA_DON c JOIN inserted i ON i.MaCTHD=c.MaCTHD
  LEFT JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=c.MaDVThucHien
  LEFT JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=c.MaCTPX
  LEFT JOIN dbo.CHI_TIET_DON_THUOC d ON d.MaCTDT=c.MaCTDT
  LEFT JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=c.MaPhieuPhuThu;
  IF EXISTS(SELECT 1 FROM dbo.HOA_DON h WHERE h.MaHD IN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted)
   AND h.GiamGia>COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=h.MaHD),0))
   THROW 51003,N''Tổng mới thấp hơn giảm giá.'',1;
  UPDATE h SET TongTien=COALESCE((SELECT SUM(c.ThanhTien) FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=h.MaHD),0)
  FROM dbo.HOA_DON h WHERE h.MaHD IN(SELECT MaHD FROM inserted UNION SELECT MaHD FROM deleted);
 END;';

 -- Bổ sung guard dùng chung cho xác nhận thường và chốt hoàn tất; giữ nguyên hai trigger cũ.
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_HD_PhuThuDichVu ON dbo.HOA_DON AFTER INSERT,UPDATE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS
   JOIN dbo.PHIEU_KHAM_BENH p WITH(HOLDLOCK) ON p.MaPhieu=l.MaPhieu
   WHERE p.PhiPhuThuDichVu>0 AND i.GiamGia>CASE WHEN i.TongTien>p.PhiPhuThuDichVu THEN i.TongTien-p.PhiPhuThuDichVu ELSE 0 END)
   THROW 53403,N''Giảm giá không được trừ vào khoản phụ thu khám dịch vụ bắt buộc.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=i.MaLS
   JOIN dbo.PHIEU_KHAM_BENH p WITH(HOLDLOCK) ON p.MaPhieu=l.MaPhieu
   WHERE p.PhiPhuThuDichVu>0 AND(i.TaoKhiHoanTat=1 OR i.TrangThai=N''Đã xác nhận'') AND NOT EXISTS(
    SELECT 1 FROM dbo.CHI_TIET_HOA_DON c WHERE c.MaHD=i.MaHD AND c.MaPhieuPhuThu=p.MaPhieu
     AND c.DonGia=p.PhiPhuThuDichVu AND c.ThanhTien=p.PhiPhuThuDichVu))
   THROW 53404,N''Hóa đơn khám dịch vụ cần đúng một dòng phụ thu 30.000đ trước khi chốt hoặc xác nhận.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.CHI_TIET_HOA_DON c ON c.MaHD=i.MaHD
   JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=c.MaPhieuPhuThu
   WHERE NOT EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaLS=i.MaLS AND l.MaPhieu=p.MaPhieu))
   THROW 53402,N''Không chuyển hóa đơn có phụ thu sang lần khám khác.'',1;
 END;';

 EXEC sys.sp_executesql N'CREATE OR ALTER VIEW dbo.VW_CHI_TIET_HOA_DON AS
 SELECT c.MaCTHD,c.MaHD,c.MaDVThucHien,c.MaCTPX,c.NoiDung,
  CASE WHEN c.MaPhieuPhuThu IS NOT NULL THEN N''Phụ thu khám dịch vụ''
   WHEN c.MaDVThucHien IS NOT NULL THEN N''Dịch vụ'' ELSE N''Thuốc'' END LoaiKhoanThu,
  CASE WHEN c.MaPhieuPhuThu IS NOT NULL THEN CAST(1 AS decimal(18,3)) ELSE COALESCE(s.SoLuong,x.SoLuong,d.SoLuong) END SoLuong,
  COALESCE(s.DonGia,c.DonGia) DonGia,
  COALESCE(d.DonViTinhChot,hh.DonViTinh) DonViTinhThuoc,c.ThanhTien,c.MaCTDT,c.MaPhieuPhuThu
 FROM dbo.CHI_TIET_HOA_DON c
 LEFT JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=c.MaDVThucHien
 LEFT JOIN dbo.CHI_TIET_PHIEU_XUAT x ON x.MaCTPX=c.MaCTPX
 LEFT JOIN dbo.CHI_TIET_DON_THUOC d ON d.MaCTDT=COALESCE(c.MaCTDT,x.MaCTDT)
 LEFT JOIN dbo.HANG_HOA hh ON hh.MaHH=x.MaHH;';

 IF OBJECT_ID(N'dbo.ANH_XQUANG_LAN_KHAM',N'U') IS NULL
 EXEC sys.sp_executesql N'CREATE TABLE [dbo].[ANH_XQUANG_LAN_KHAM]
 (
  MaAnh nvarchar(50) NOT NULL CONSTRAINT PK_ANH_XQUANG_LAN_KHAM PRIMARY KEY,
  MaLS nvarchar(50) NOT NULL,
  MaDVThucHien nvarchar(50) NULL,
  TenTepGoc nvarchar(255) NOT NULL,
  TenTepLuu nvarchar(255) NOT NULL,
  DuongDanTuongDoi nvarchar(500) NOT NULL,
  MimeType nvarchar(100) NOT NULL,
  KichThuocBytes bigint NOT NULL,
  Sha256 char(64) NOT NULL,
  GhiChu nvarchar(500) NULL,
  NgayTao datetime2(0) NOT NULL CONSTRAINT DF_AXQ_NgayTao DEFAULT(SYSDATETIME()),
  MaNVUpload nvarchar(50) NOT NULL,
  TrangThai nvarchar(20) NOT NULL CONSTRAINT DF_AXQ_TrangThai DEFAULT(N''Đang sử dụng''),
  NgayAn datetime2(0) NULL,
  CONSTRAINT FK_AXQ_LanKham FOREIGN KEY(MaLS) REFERENCES dbo.LICH_SU_KHAM_BENH(MaLS),
  CONSTRAINT FK_AXQ_DichVu FOREIGN KEY(MaDVThucHien) REFERENCES dbo.DICH_VU_THUC_HIEN(MaDVThucHien),
  CONSTRAINT FK_AXQ_NhanVien FOREIGN KEY(MaNVUpload) REFERENCES dbo.NHAN_VIEN(MaNV),
  CONSTRAINT CK_AXQ_KichThuoc CHECK(KichThuocBytes>0 AND KichThuocBytes<=20971520),
  CONSTRAINT CK_AXQ_Hash CHECK(LEN(Sha256)=64 AND Sha256 COLLATE Latin1_General_100_BIN2 NOT LIKE ''%[^0-9a-fA-F]%''),
  -- Khóa lưu trữ một cấp: GUID 32 chữ số hex + đuôi; không có tên bệnh nhân hay đường dẫn máy trạm.
  CONSTRAINT CK_AXQ_Tep CHECK(
   ((MimeType=N''image/png'' AND RIGHT(TenTepLuu,4)=N''.png'' AND LEN(TenTepLuu)=36)
    OR(MimeType=N''image/jpeg'' AND((RIGHT(TenTepLuu,4)=N''.jpg'' AND LEN(TenTepLuu)=36)
     OR(RIGHT(TenTepLuu,5)=N''.jpeg'' AND LEN(TenTepLuu)=37))))
   AND LEFT(TenTepLuu,32) COLLATE Latin1_General_100_BIN2 NOT LIKE N''%[^0-9a-fA-F]%''
   AND DuongDanTuongDoi=TenTepLuu AND DATALENGTH(DuongDanTuongDoi)=DATALENGTH(TenTepLuu)
   AND LEN(TenTepGoc)>0 AND TenTepGoc NOT LIKE N''%[/:\]%''),
  CONSTRAINT CK_AXQ_TrangThai CHECK((TrangThai=N''Đang sử dụng'' AND NgayAn IS NULL)
   OR(TrangThai=N''Đã ẩn'' AND NgayAn IS NOT NULL AND NgayAn>=NgayTao))
 );
 CREATE UNIQUE INDEX UX_AXQ_DuongDan ON dbo.ANH_XQUANG_LAN_KHAM(DuongDanTuongDoi);
 CREATE INDEX IX_AXQ_LanKham_NgayTao ON dbo.ANH_XQUANG_LAN_KHAM(MaLS,NgayTao);';

 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_AXQ_BaoVe ON dbo.ANH_XQUANG_LAN_KHAM AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaAnh=d.MaAnh WHERE i.MaAnh IS NULL)
   THROW 53407,N''Không xóa cứng metadata ảnh bệnh án; dùng trạng thái Đã ẩn.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaAnh=i.MaAnh WHERE EXISTS(
   SELECT i.MaLS,i.MaDVThucHien,i.TenTepGoc,i.TenTepLuu,i.DuongDanTuongDoi,i.MimeType,i.KichThuocBytes,i.Sha256,i.NgayTao,i.MaNVUpload
   EXCEPT SELECT d.MaLS,d.MaDVThucHien,d.TenTepGoc,d.TenTepLuu,d.DuongDanTuongDoi,d.MimeType,d.KichThuocBytes,d.Sha256,d.NgayTao,d.MaNVUpload))
   THROW 53405,N''Nguồn lần khám, tệp và người tải ảnh được giữ nguyên; chỉ sửa ghi chú hoặc ẩn ảnh.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=i.MaDVThucHien WHERE s.MaLS<>i.MaLS)
   THROW 53406,N''Dịch vụ liên kết ảnh phải thuộc cùng lần khám.'',1;
 END;';

 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_DVTH_AnhXquang ON dbo.DICH_VU_THUC_HIEN AFTER UPDATE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.ANH_XQUANG_LAN_KHAM a ON a.MaDVThucHien=i.MaDVThucHien WHERE a.MaLS<>i.MaLS)
   THROW 53406,N''Dịch vụ đã liên kết ảnh không được chuyển sang lần khám khác.'',1;
 END;';
 EXEC sys.sp_executesql N'CREATE OR ALTER TRIGGER dbo.TR_LS_NguonAnhPhuThu ON dbo.LICH_SU_KHAM_BENH AFTER UPDATE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaLS=i.MaLS WHERE i.MaPhieu<>d.MaPhieu
   AND(EXISTS(SELECT 1 FROM dbo.ANH_XQUANG_LAN_KHAM a WHERE a.MaLS=i.MaLS)
    OR EXISTS(SELECT 1 FROM dbo.HOA_DON h JOIN dbo.CHI_TIET_HOA_DON c ON c.MaHD=h.MaHD WHERE h.MaLS=i.MaLS AND c.MaPhieuPhuThu IS NOT NULL)))
   THROW 53409,N''Lần khám có ảnh hoặc phụ thu không được đổi phiếu nguồn.'',1;
 END;';

 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraNenTangSprint3 AS
 BEGIN
  SET NOCOUNT ON;
  IF ISNULL(COL_LENGTH(N''dbo.PHIEU_KHAM_BENH'',N''LoaiKham''),-1)<>40
   OR ISNULL(COL_LENGTH(N''dbo.PHIEU_KHAM_BENH'',N''PhiPhuThuDichVu''),-1)<>9
   OR ISNULL(COL_LENGTH(N''dbo.CHI_TIET_HOA_DON'',N''MaPhieuPhuThu''),-1)<>100
   OR OBJECT_ID(N''dbo.ANH_XQUANG_LAN_KHAM'',N''U'') IS NULL
   THROW 53408,N''Thiếu hoặc sai schema nền tảng Sprint 3.'',1;
  IF EXISTS(SELECT 1 FROM(VALUES
   (N''PHIEU_KHAM_BENH'',N''LoaiKham'',231,40,0,0,0),
   (N''PHIEU_KHAM_BENH'',N''PhiPhuThuDichVu'',106,9,18,2,0),
   (N''CHI_TIET_HOA_DON'',N''MaPhieuPhuThu'',231,100,0,0,1)) required(T,C,TypeId,L,P,S,N)
   LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.''+required.T) AND c.name=required.C
   WHERE c.column_id IS NULL OR c.system_type_id<>required.TypeId OR c.max_length<>required.L OR c.is_nullable<>required.N
    OR(required.TypeId=106 AND(c.precision<>required.P OR c.scale<>required.S)))
   THROW 53408,N''Sai kiểu hoặc nullability cột khám dịch vụ/phụ thu.'',1;
  IF EXISTS(SELECT name FROM(VALUES(N''CK_PKB_LoaiKham_PhuThu''),(N''CK_CHI_TIET_HOA_DON_3''),
   (N''CK_AXQ_Tep''),(N''CK_AXQ_Hash''),(N''CK_AXQ_KichThuoc''),(N''CK_AXQ_TrangThai'')) required(name)
   WHERE NOT EXISTS(SELECT 1 FROM sys.check_constraints c WHERE c.name=required.name AND c.is_disabled=0 AND c.is_not_trusted=0))
   THROW 53408,N''Thiếu CHECK tin cậy của nền tảng Sprint 3.'',1;
  IF EXISTS(SELECT name FROM(VALUES(N''FK_CTHD_PhieuPhuThu''),(N''FK_AXQ_LanKham''),(N''FK_AXQ_DichVu''),(N''FK_AXQ_NhanVien'')) required(name)
   WHERE NOT EXISTS(SELECT 1 FROM sys.foreign_keys f WHERE f.name=required.name AND f.is_disabled=0 AND f.is_not_trusted=0))
   THROW 53408,N''Thiếu FK tin cậy của nền tảng Sprint 3.'',1;
  IF EXISTS(SELECT name FROM(VALUES(N''TR_PKB_KhoaLoaiKham''),(N''TR_CTHD_TinhTien''),(N''TR_HD_PhuThuDichVu''),
   (N''TR_HD_XacNhan''),(N''TR_HD_ChotHoanTat''),(N''TR_AXQ_BaoVe''),(N''TR_DVTH_AnhXquang''),(N''TR_LS_NguonAnhPhuThu'')) required(name)
   WHERE NOT EXISTS(SELECT 1 FROM sys.triggers t WHERE t.name=required.name AND t.is_disabled=0))
   THROW 53408,N''Thiếu trigger đang hoạt động của nền tảng Sprint 3.'',1;
  IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.CHI_TIET_HOA_DON'') AND name=N''UX_CTHD_PhieuPhuThu'' AND is_unique=1 AND has_filter=1 AND is_disabled=0)
   OR NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N''dbo.ANH_XQUANG_LAN_KHAM'') AND name=N''UX_AXQ_DuongDan'' AND is_unique=1 AND is_disabled=0)
   THROW 53408,N''Thiếu index chống trùng phụ thu hoặc đường dẫn ảnh.'',1;
  IF EXISTS(SELECT 1 FROM dbo.CHI_TIET_HOA_DON c JOIN dbo.HOA_DON h ON h.MaHD=c.MaHD
   JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=c.MaPhieuPhuThu
   WHERE p.LoaiKham<>N''Dịch vụ'' OR c.DonGia<>p.PhiPhuThuDichVu OR c.ThanhTien<>p.PhiPhuThuDichVu
    OR NOT EXISTS(SELECT 1 FROM dbo.LICH_SU_KHAM_BENH l WHERE l.MaLS=h.MaLS AND l.MaPhieu=p.MaPhieu))
   THROW 53408,N''Có dòng phụ thu không khớp nguồn.'',1;
  IF EXISTS(SELECT 1 FROM dbo.ANH_XQUANG_LAN_KHAM a JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=a.MaDVThucHien WHERE a.MaLS<>s.MaLS)
   THROW 53408,N''Có ảnh tham chiếu dịch vụ của lần khám khác.'',1;
  SELECT N''Sprint3Foundation1'' AS HopDong,COUNT_BIG(*) AS SoAnh FROM dbo.ANH_XQUANG_LAN_KHAM;
 END;';
 EXEC dbo.usp_RHM_KiemTraNenTangSprint3;
 IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.Sprint3Foundation.Version')
  EXEC sys.sp_addextendedproperty @name=N'RHM.Sprint3Foundation.Version',@value=1;
 COMMIT TRANSACTION;
 EXEC sys.sp_set_session_context @key=N'RHM.Sprint3Foundation.Completed',@value=1;
 PRINT N'Sprint3Foundation1: loại khám/phụ thu, nguồn hóa đơn và metadata ảnh đã sẵn sàng.';
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO
-- END SPRINT 3 FOUNDATION 20261107

-- BEGIN XRAY STORAGE P4: phân công ảnh tách khỏi người thực hiện dịch vụ đã chốt.
SET XACT_ABORT ON;
EXEC sys.sp_set_session_context @key=N'RHM.XrayStorage.Completed',@value=0;
BEGIN TRY
 BEGIN TRANSACTION;
 IF OBJECT_ID(N'dbo.ANH_XQUANG_LAN_KHAM',N'U') IS NULL THROW 53410,N'Cần nền tảng ảnh P1 trước P4.',1;
 IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.HospitalWorkflow.Completed')),0)<>1
  OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.PrescriptionFlow.Completed')),0)<>1
  OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.SqlV9.Completed')),0)<>1
  OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.Sprint3Foundation.Completed')),0)<>1 THROW 53410,N'Các pha SQL trước P4 chưa hoàn tất.',1;
 DECLARE @xrMigrationLock int;
 EXEC @xrMigrationLock=sys.sp_getapplock @Resource=N'RHM:Xray:Storage',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=15000;
 IF @xrMigrationLock<0 THROW 53410,N'Kho ảnh đang có thao tác; thử nâng cấp lại sau.',1;
 IF OBJECT_ID(N'dbo.PHAN_CONG_ANH_XQUANG',N'U') IS NULL
 EXEC(N'CREATE TABLE [dbo].[PHAN_CONG_ANH_XQUANG](
  MaPC nvarchar(50) NOT NULL CONSTRAINT PK_PHAN_CONG_ANH_XQUANG PRIMARY KEY,
  MaDVThucHien nvarchar(50) NOT NULL,
  MaNVKyThuat nvarchar(50) NOT NULL,
  MaNVPhanCong nvarchar(50) NOT NULL,
  NgayPhanCong datetime2(0) NOT NULL CONSTRAINT DF_PCAXQ_Ngay DEFAULT(SYSDATETIME()),
  TrangThai nvarchar(20) NOT NULL CONSTRAINT DF_PCAXQ_TrangThai DEFAULT(N''Đang áp dụng''),
  NgayHuy datetime2(0) NULL,
  CONSTRAINT FK_PCAXQ_DichVu FOREIGN KEY(MaDVThucHien) REFERENCES dbo.DICH_VU_THUC_HIEN(MaDVThucHien),
  CONSTRAINT FK_PCAXQ_KyThuat FOREIGN KEY(MaNVKyThuat) REFERENCES dbo.NHAN_VIEN(MaNV),
  CONSTRAINT FK_PCAXQ_NguoiGiao FOREIGN KEY(MaNVPhanCong) REFERENCES dbo.NHAN_VIEN(MaNV),
  CONSTRAINT CK_PCAXQ_TrangThai CHECK((TrangThai=N''Đang áp dụng'' AND NgayHuy IS NULL)
   OR(TrangThai=N''Đã hủy'' AND NgayHuy IS NOT NULL AND NgayHuy>=NgayPhanCong)));
  CREATE UNIQUE INDEX UX_PCAXQ_DichVu ON dbo.PHAN_CONG_ANH_XQUANG(MaDVThucHien) WHERE TrangThai=N''Đang áp dụng'';
  CREATE INDEX IX_PCAXQ_NhanVien ON dbo.PHAN_CONG_ANH_XQUANG(MaNVKyThuat,TrangThai);');
 EXEC(N'CREATE OR ALTER TRIGGER dbo.TR_PCAXQ_BaoVe ON dbo.PHAN_CONG_ANH_XQUANG AFTER INSERT,UPDATE,DELETE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.MaPC=d.MaPC WHERE i.MaPC IS NULL)
   THROW 53411,N''Không xóa lịch sử phân công ảnh.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaPC=i.MaPC WHERE d.TrangThai=N''Đã hủy''
   OR EXISTS(SELECT i.MaDVThucHien,i.MaNVKyThuat,i.MaNVPhanCong,i.NgayPhanCong EXCEPT SELECT d.MaDVThucHien,d.MaNVKyThuat,d.MaNVPhanCong,d.NgayPhanCong))
   THROW 53412,N''Phân công ảnh đã lưu được giữ nguyên; hủy và lập phân công mới.'',1;
  IF EXISTS(SELECT 1 FROM inserted i JOIN dbo.DICH_VU_THUC_HIEN s ON s.MaDVThucHien=i.MaDVThucHien
   JOIN dbo.DICH_VU d ON d.MaDV=s.MaDV JOIN dbo.LICH_SU_KHAM_BENH l ON l.MaLS=s.MaLS
   JOIN dbo.PHIEU_KHAM_BENH p ON p.MaPhieu=l.MaPhieu JOIN dbo.NHAN_VIEN n ON n.MaNV=i.MaNVKyThuat
   WHERE d.MaCK<>N''CK004'' OR l.TrangThai<>N''Nháp'' OR p.TrangThai NOT IN(N''Chờ khám'',N''Đang khám'')
    OR(i.TrangThai=N''Đang áp dụng'' AND(n.MaChucVu<>N''CV003'' OR n.TrangThai<>N''Đang làm việc'' OR NOT EXISTS(SELECT 1 FROM dbo.TAI_KHOAN t WHERE t.MaNV=n.MaNV AND t.TrangThai=N''Đang hoạt động''))))
   THROW 53413,N''Phân công cần dịch vụ chụp, lượt còn mở và nhân viên kỹ thuật đang hoạt động.'',1;
 END;');
 EXEC(N'CREATE OR ALTER TRIGGER dbo.TR_DVTH_PCAXQ ON dbo.DICH_VU_THUC_HIEN AFTER UPDATE AS
 BEGIN
  SET NOCOUNT ON;
  IF EXISTS(SELECT 1 FROM inserted i JOIN deleted d ON d.MaDVThucHien=i.MaDVThucHien
   WHERE(i.MaLS<>d.MaLS OR i.MaDV<>d.MaDV) AND EXISTS(SELECT 1 FROM dbo.PHAN_CONG_ANH_XQUANG pc WHERE pc.MaDVThucHien=i.MaDVThucHien))
   THROW 53414,N''Dịch vụ có lịch sử phân công ảnh giữ nguyên nguồn lượt và loại dịch vụ.'',1;
 END;');
 EXEC(N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraKhoAnh AS
 BEGIN
  SET NOCOUNT ON;
  IF OBJECT_ID(N''dbo.PHAN_CONG_ANH_XQUANG'',N''U'') IS NULL OR OBJECT_ID(N''dbo.TR_PCAXQ_BaoVe'',N''TR'') IS NULL OR OBJECT_ID(N''dbo.TR_DVTH_PCAXQ'',N''TR'') IS NULL
   THROW 53415,N''Chưa đồng bộ phân công ảnh P4.'',1;
  IF EXISTS(SELECT 1 FROM(VALUES
   (N''FK_PCAXQ_DichVu'',N''MaDVThucHien'',N''DICH_VU_THUC_HIEN'',N''MaDVThucHien''),
   (N''FK_PCAXQ_KyThuat'',N''MaNVKyThuat'',N''NHAN_VIEN'',N''MaNV''),
   (N''FK_PCAXQ_NguoiGiao'',N''MaNVPhanCong'',N''NHAN_VIEN'',N''MaNV'')) required(N,C,RT,RC)
   WHERE NOT EXISTS(SELECT 1 FROM sys.foreign_keys f JOIN sys.foreign_key_columns k ON k.constraint_object_id=f.object_id
    JOIN sys.columns c ON c.object_id=k.parent_object_id AND c.column_id=k.parent_column_id
    JOIN sys.columns r ON r.object_id=k.referenced_object_id AND r.column_id=k.referenced_column_id
    WHERE f.object_id=OBJECT_ID(N''dbo.''+required.N,N''F'') AND f.parent_object_id=OBJECT_ID(N''dbo.PHAN_CONG_ANH_XQUANG'')
     AND f.referenced_object_id=OBJECT_ID(N''dbo.''+required.RT) AND c.name=required.C AND r.name=required.RC
     AND f.is_disabled=0 AND f.is_not_trusted=0 AND k.constraint_column_id=1
     AND(SELECT COUNT(*) FROM sys.foreign_key_columns k2 WHERE k2.constraint_object_id=f.object_id)=1))
   THROW 53415,N''Thiếu FK phân công ảnh đã kiểm chứng.'',1;
  IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N''CK_PCAXQ_TrangThai'' AND is_disabled=0 AND is_not_trusted=0)
   OR NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N''dbo.PHAN_CONG_ANH_XQUANG'') AND i.name=N''UX_PCAXQ_DichVu'' AND i.is_unique=1 AND i.is_disabled=0
    AND i.has_filter=1 AND i.filter_definition=N''([TrangThai]=N''''Đang áp dụng'''')''
    AND EXISTS(SELECT 1 FROM sys.index_columns k JOIN sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id
     WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND k.key_ordinal=1 AND c.name=N''MaDVThucHien'')
    AND(SELECT COUNT(*) FROM sys.index_columns k WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND k.key_ordinal>0)=1)
   THROW 53415,N''Thiếu CHECK/index phân công ảnh.'',1;
  IF EXISTS(SELECT 1 FROM(VALUES(N''TR_PCAXQ_BaoVe'',N''PHAN_CONG_ANH_XQUANG''),(N''TR_DVTH_PCAXQ'',N''DICH_VU_THUC_HIEN'')) required(N,T)
   WHERE NOT EXISTS(SELECT 1 FROM sys.triggers t WHERE t.object_id=OBJECT_ID(N''dbo.''+required.N,N''TR'')
    AND t.parent_id=OBJECT_ID(N''dbo.''+required.T) AND t.is_disabled=0))
   THROW 53415,N''Trigger bảo vệ phân công ảnh bị thiếu, sai bảng hoặc đã tắt.'',1;
  -- Đối chiếu đủ thuộc tính ET để DAL không nhận lỗi cột/kiểu sau khi kiểm schema thành công.
  IF EXISTS(SELECT 1 FROM(VALUES
   (N''ANH_XQUANG_LAN_KHAM'',N''MaAnh'',231,100,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''MaLS'',231,100,0,0),
   (N''ANH_XQUANG_LAN_KHAM'',N''MaDVThucHien'',231,100,0,1),(N''ANH_XQUANG_LAN_KHAM'',N''TenTepGoc'',231,510,0,0),
   (N''ANH_XQUANG_LAN_KHAM'',N''TenTepLuu'',231,510,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''DuongDanTuongDoi'',231,1000,0,0),
   (N''ANH_XQUANG_LAN_KHAM'',N''MimeType'',231,200,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''KichThuocBytes'',127,8,0,0),
   (N''ANH_XQUANG_LAN_KHAM'',N''Sha256'',175,64,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''GhiChu'',231,1000,0,1),
   (N''ANH_XQUANG_LAN_KHAM'',N''NgayTao'',42,6,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''MaNVUpload'',231,100,0,0),
   (N''ANH_XQUANG_LAN_KHAM'',N''TrangThai'',231,40,0,0),(N''ANH_XQUANG_LAN_KHAM'',N''NgayAn'',42,6,0,1),
   (N''PHAN_CONG_ANH_XQUANG'',N''MaPC'',231,100,0,0),(N''PHAN_CONG_ANH_XQUANG'',N''MaDVThucHien'',231,100,0,0),
   (N''PHAN_CONG_ANH_XQUANG'',N''MaNVKyThuat'',231,100,0,0),(N''PHAN_CONG_ANH_XQUANG'',N''MaNVPhanCong'',231,100,0,0),
   (N''PHAN_CONG_ANH_XQUANG'',N''NgayPhanCong'',42,6,0,0),(N''PHAN_CONG_ANH_XQUANG'',N''TrangThai'',231,40,0,0),
   (N''PHAN_CONG_ANH_XQUANG'',N''NgayHuy'',42,6,0,1)) required(T,C,TypeId,L,S,N)
   LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N''dbo.''+required.T) AND c.name=required.C
   WHERE c.column_id IS NULL OR c.system_type_id<>required.TypeId OR c.max_length<>required.L OR c.scale<>required.S OR c.is_nullable<>required.N)
   THROW 53415,N''Cột metadata/phân công ảnh không khớp ET/DAL hiện tại.'',1;
  EXEC dbo.usp_RHM_KiemTraNenTangSprint3;
 END;');
 EXEC dbo.usp_RHM_KiemTraKhoAnh;
 IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'RHM.XrayStorage.Version')
  EXEC sys.sp_addextendedproperty @name=N'RHM.XrayStorage.Version',@value=1;
 COMMIT;
 EXEC sys.sp_set_session_context @key=N'RHM.XrayStorage.Completed',@value=1;
 PRINT N'XrayStorage1: phân công ảnh, metadata và bảo vệ lịch sử sẵn sàng; kho tệp cấu hình riêng.';
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
-- END XRAY STORAGE P4

-- BEGIN PROJECT SCHEMA SYNC 20261110: định nghĩa kiểm tổng phải đặt cuối sau P1/P4.
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.Sprint3Foundation.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.XrayStorage.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.HospitalWorkflow.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.PrescriptionFlow.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.SqlV9.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.MaintenanceSerial.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.RolePermissions.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.AuditSchema.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.AuditTriggers.Completed')),0)<>1
 OR COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'RHM.PayrollCatalog.Completed')),0)<>1
 THROW 53416,N'Có pha SQL chưa hoàn tất; chạy lại toàn bộ file sau khi xử lý lỗi, không bỏ qua lỗi batch.',1;
BEGIN TRY
 BEGIN TRANSACTION;
 EXEC sys.sp_executesql N'CREATE OR ALTER PROCEDURE dbo.usp_RHM_KiemTraSchema AS
 BEGIN
  SET NOCOUNT ON;
  EXEC dbo.usp_RHM_KiemTraSchemaNen;
  EXEC dbo.usp_RHM_KiemTraKeThuoc;
  EXEC dbo.usp_RHM_KiemTraDongBoV9;
  EXEC dbo.usp_RHM_KiemTraBaoTriSerial;
  IF NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N''dbo.NHAT_KY_THAO_TAC'') AND i.name=N''UX_S3_Event''
   AND i.is_unique=1 AND i.is_disabled=0 AND i.has_filter=1 AND i.filter_definition=N''([MaSuKien] IS NOT NULL)''
   AND EXISTS(SELECT 1 FROM sys.index_columns k JOIN sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id
    WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND k.key_ordinal=1 AND c.name=N''MaSuKien'')
   AND(SELECT COUNT(*) FROM sys.index_columns k WHERE k.object_id=i.object_id AND k.index_id=i.index_id AND k.key_ordinal>0)=1)
   THROW 53417,N''Thiếu hoặc sai index chống trùng sự kiện nhật ký ứng dụng.'',1;
  -- Kiểm kho ảnh gọi tiếp nền tảng Sprint3, bao gồm loại khám/phụ thu/hóa đơn.
  EXEC dbo.usp_RHM_KiemTraKhoAnh;
 END;';
 EXEC dbo.usp_RHM_KiemTraSchema;
 COMMIT TRANSACTION;
 PRINT N'PROJECT_SCHEMA_READY: 64 bảng và các liên kết ET/DAL/BUS/WPF đã kiểm tra; cấu hình SQL Server/kho ảnh tại appsettings.json.';
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
GO
-- END PROJECT SCHEMA SYNC 20261110
